-- Import of CGM - Porto Velho/RO 2026 official exam items for career "Auditor"
-- (Edital nº 2 - CGM - Porto Velho/RO, de 27 de abril de 2026, CEBRASPE).
-- This is the only cargo of this contest that was fully importable: Cargo 1
-- (Auditor) has 80 objective items with a verified gabarito for both
-- Conhecimentos Gerais (1-30) and Conhecimentos Específicos (31-80). Cargo 2
-- (Contador) and Cargo 3 (Técnico de Controle Interno) also exist in this
-- same concurso but their prova/gabarito files were NOT found in the user's
-- Google Drive "CONTROLADORIA GERAL DO MUNÍCIPIO PORTO VELHO" folder, so
-- they are NOT imported here (see report).
--
-- Source material:
--   - Prova (Conhecimentos Gerais - Cargo 1): read verbatim from Google Drive
--     fileId 1tTgCuY-dgiPIL2xDS3G6LeauEsh-cUAW ("PROVA OBJETIVA –
--     CONHECIMENTOS GERAIS – CARGO 1.pdf") and cross-checked against the
--     official CEBRASPE CDN copy.
--   - Prova (Conhecimentos Específicos - Cargo 1): read verbatim from Google
--     Drive fileId 19wO9dG4akf1_cJbbm6oxMZzKuoGyLVBW ("PROVA OBJETIVA –
--     CONHECIMENTOS ESPECÍFICOS – CARGO 1.pdf").
--   - Gabarito (Conhecimentos Específicos, itens 31-80): Google Drive fileId
--     1ylVNzFmFRXa5vl8ahL5_udX66E3GzDgC ("GABARITO DEFINITIVO –
--     CONHECIMENTOS ESPECÍFICOS – CARGO 1.pdf"), labeled
--     211_CGMROAUDITOR_001_01, "CARGO 1: AUDITOR".
--   - Gabarito (Conhecimentos Gerais, itens 1-30): NOT present in the Drive
--     folder. Confirmed the file exists officially on the CEBRASPE contest
--     portal (www.cebraspe.org.br/concursos/cgm_porto_velho_ro_26, listed
--     as "GABARITO DEFINITIVO – CONHECIMENTOS GERAIS – CARGO 1", published
--     02/09/2026) and read it directly from the official CEBRASPE CDN, since
--     it was missing from the Drive folder but is required by governance
--     (no guessing answers).
--   - Item 54 (Conhecimentos Específicos) is marked "X" (anulado) in the
--     official gabarito and is imported with content_status='annulled', per
--     governance (annulled items are never shown to students). All other 79
--     items had a definite letter answer (A-E), no other item was annulled.
--
-- No discursive items (redação / questão discursiva) are imported: the
-- official_exam_questions table models single-answer objective items only.

insert into public.content_sources (source_type,title,issuer,url,status,notes) values
('outro','Prova objetiva CGM Porto Velho - Auditor - Conhecimentos Gerais - 2026','CGM Porto Velho/RO / CEBRASPE','https://cdn.cebraspe.org.br/concursos/cgm_porto_velho_ro_26/arquivos/2B0AA311FB1CDEC9C1AC8AC3318B712AFDC0E7248BEF86D3FB02C5B9BA133C8C.pdf','vigente','Caderno oficial de Conhecimentos Gerais, Cargo 1: Auditor (Google Drive fileId 1tTgCuY-dgiPIL2xDS3G6LeauEsh-cUAW, texto lido verbatim nesta sessão e conferido contra a cópia oficial no CDN da CEBRASPE).'),
('outro','Prova objetiva CGM Porto Velho - Auditor - Conhecimentos Específicos - 2026','CGM Porto Velho/RO / CEBRASPE','https://cdn.cebraspe.org.br/concursos/cgm_porto_velho_ro_26/arquivos/2559554662B5E5D9594E6E426AEED58F3469E6B856573355FD8B3C9D7BF8A30A.pdf','vigente','Caderno oficial de Conhecimentos Específicos, Cargo 1: Auditor (Google Drive fileId 19wO9dG4akf1_cJbbm6oxMZzKuoGyLVBW, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo CGM Porto Velho - Auditor - Conhecimentos Gerais - 2026','CGM Porto Velho/RO / CEBRASPE','https://cdn.cebraspe.org.br/concursos/cgm_porto_velho_ro_26/arquivos/9B041111FB0F5C49C1ADF4F29BD0F55313F7A9C13D9A03AC45F11C4C76848912.pdf','vigente','Gabarito oficial definitivo de Conhecimentos Gerais, Cargo 1: Auditor. Ausente na pasta do Google Drive do usuário; lido diretamente do CDN oficial da CEBRASPE nesta sessão. Itens 1-30, nenhum anulado.'),
('outro','Gabarito definitivo CGM Porto Velho - Auditor - Conhecimentos Específicos - 2026','CGM Porto Velho/RO / CEBRASPE','https://cdn.cebraspe.org.br/concursos/cgm_porto_velho_ro_26/arquivos/ADDC4DCC2133882E801EB6E9EDAAE57E1B98E20D60ACAB34826B9BE4AA6DC528.pdf','vigente','Gabarito oficial definitivo de Conhecimentos Específicos (Matriz 211_CGMROAUDITOR_001_01), explicitamente rotulado CARGO 1: AUDITOR (Google Drive fileId 1ylVNzFmFRXa5vl8ahL5_udX66E3GzDgC). Itens 31-80; item 54 anulado (X), demais com gabarito definitivo A-E.')
on conflict (url) do update set checked_at=now(),status=excluded.status,notes=excluded.notes;

insert into public.syllabus_editions (contest_name,role_name,contest_year,source_id)
select 'Controladoria-Geral do Município de Porto Velho (CGM/RO)','Auditor',2026,(select id from public.content_sources where url=$q$https://cdn.cebraspe.org.br/concursos/cgm_porto_velho_ro_26/arquivos/2B0AA311FB1CDEC9C1AC8AC3318B712AFDC0E7248BEF86D3FB02C5B9BA133C8C.pdf$q$)
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Controladoria-Geral do Município de Porto Velho (CGM/RO)' and role_name='Auditor' and contest_year=2026
);

-- Discipline breakdown derived directly from the prova's own section headers
-- and command-block codes embedded in each item (e.g. CG1A1 for the
-- Conhecimentos Gerais reading text; A01-A06 blocks for Conhecimentos
-- Específicos), not guessed.
with edition as (
  select id from public.syllabus_editions
  where contest_name='Controladoria-Geral do Município de Porto Velho (CGM/RO)' and role_name='Auditor' and contest_year=2026
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de texto, tipologia textual, coesão, morfossintaxe, regência, crase e reescrita de períodos (itens 1-9 da prova de Conhecimentos Gerais).'),
  ('Raciocínio Lógico-Matemático','Resolução de problemas com sistemas de equações, probabilidade e funções quadráticas aplicadas (itens 10-12).'),
  ('Direito Administrativo','Controle interno e externo da administração pública, competências do TCU, sistemas de controle jurisdicional (contencioso administrativo e jurisdição una) e processo administrativo municipal (Lei Complementar municipal nº 745/2018).'),
  ('Administração Geral','Abordagens clássica, burocrática e sistêmica da administração; funções de planejamento, organização, direção e controle; motivação, liderança e desempenho; viabilidade econômico-financeira de projetos.'),
  ('Direito Constitucional','Competências constitucionais do Congresso Nacional, da Câmara dos Deputados e do Senado Federal; aplicabilidade e eficácia das normas constitucionais; processo legislativo e sanção/veto presidencial.'),
  ('Proteção de Dados Pessoais (LGPD)','Regime de responsabilidade dos agentes de tratamento (controlador e operador) e tratamento de dados pessoais pelo poder público, conforme a Lei Geral de Proteção de Dados Pessoais.'),
  ('Licitações e Contratos','Modalidades e modos de disputa da Lei nº 14.133/2021 (pregão, concorrência), critérios de julgamento e divulgação obrigatória no Portal Nacional de Contratações Públicas (PNCP).'),
  ('Tecnologia da Informação','Dados estruturados e não estruturados, modelagem de dados, álgebra relacional, integridade referencial, mineração de dados e ferramentas de visualização (Power BI e Tableau).'),
  ('Orçamento Público','Funções de intervenção na economia, orçamento-programa, plano plurianual (PPA), créditos adicionais, receita pública, restos a pagar, despesas de exercícios anteriores, termo de execução descentralizada e decreto de programação orçamentária e financeira (DPOF).'),
  ('Políticas Públicas','Conceito e ciclo de políticas públicas, estruturas de poder em políticas redistributivas, abordagem policêntrica, definição de agenda, nodalidade, indicadores de desempenho e avaliação formativa.'),
  ('Finanças Públicas','Função distributiva do Estado, curva de Laffer, equidade tributária, transferências voluntárias, Lei de Responsabilidade Fiscal (ajuste fiscal, operações de crédito, limites de despesa com pessoal) e elaboração da LOA.'),
  ('Auditoria Governamental','Normas ISSAI de auditoria financeira e de conformidade, materialidade, amostragem, papéis de trabalho, avaliação de risco de distorção relevante e relato de achados em auditoria operacional.'),
  ('Planejamento e Controle Orçamentário','Natureza jurídica do planejamento governamental, PPA/LOA/LDO, classificação funcional da despesa, processo legislativo orçamentário, controle interno/externo, tipos de auditoria e relatórios RREO/RGF.'),
  ('Lei Anticorrupção','Responsabilização administrativa e judicial de pessoas jurídicas, acordo de leniência, dosimetria de sanções, CNEP/CEIS e publicação extraordinária da decisão condenatória, conforme a Lei nº 12.846/2013.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2026,1,$q$Língua Portuguesa$q$,$q$Infere-se do texto CG1A1 que A o aprimoramento dos processos de gestão se destaca como o principal benefício da IA no setor público. B o principal objetivo da criação da assistente virtual Clara foi elevar o índice de transparência de Rondônia para a faixa exigida pelo Programa Nacional de Transparência Pública. C a implantação da assistente virtual Clara é uma iniciativa voltada principalmente à impreterível substituição do atendimento humano nos serviços públicos. D o índice de transparência de 99,29% alcançado por Rondônia é atribuído à implantação da assistente virtual Clara. E a capacidade da IA de aprender e se adaptar continuamente é uma das principais justificativas para sua adoção no setor público.$q$,$q$Infere-se do texto CG1A1 que A o aprimoramento dos processos de gestão se destaca como o principal benefício da IA no setor público. B o principal objetivo da criação da assistente virtual Clara foi elevar o índice de transparência de Rondônia para a faixa exigida pelo Programa Nacional de Transparência Pública. C a implantação da assistente virtual Clara é uma iniciativa voltada principalmente à impreterível substituição do atendimento humano nos serviços públicos. D o índice de transparência de 99,29% alcançado por Rondônia é atribuído à implantação da assistente virtual Clara. E a capacidade da IA de aprender e se adaptar continuamente é uma das principais justificativas para sua adoção no setor público.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,2,$q$Língua Portuguesa$q$,$q$No que se refere à tipologia textual, o texto CG1A1 caracteriza-se como predominantemente A argumentativo, por defender a adoção da IA como estratégia indispensável para a modernização do setor público. B narrativo, em razão do encadeamento temporal dos fatos relacionados ao desenvolvimento e ao lançamento da assistente virtual Clara. C descritivo, em virtude da apresentação detalhada das características e capacidades da assistente virtual Clara. D injuntivo, por orientar o leitor acerca das formas de utilização da IA na administração pública. E expositivo, por apresentar informações e esclarecimentos sobre a criação da assistente virtual Clara e sua relevância para a gestão pública rondoniana.$q$,$q$No que se refere à tipologia textual, o texto CG1A1 caracteriza-se como predominantemente A argumentativo, por defender a adoção da IA como estratégia indispensável para a modernização do setor público. B narrativo, em razão do encadeamento temporal dos fatos relacionados ao desenvolvimento e ao lançamento da assistente virtual Clara. C descritivo, em virtude da apresentação detalhada das características e capacidades da assistente virtual Clara. D injuntivo, por orientar o leitor acerca das formas de utilização da IA na administração pública. E expositivo, por apresentar informações e esclarecimentos sobre a criação da assistente virtual Clara e sua relevância para a gestão pública rondoniana.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,3,$q$Língua Portuguesa$q$,$q$A respeito dos mecanismos de coesão empregados no texto CG1A1, assinale a opção correta. A No último parágrafo, o trecho ‘Ao contrário de outras tecnologias’ estabelece uma relação de alternância entre as características da IA e as das demais tecnologias. B No trecho entre aspas no quinto parágrafo, a expressão ‘Por isso’ introduz uma conclusão. C No quarto parágrafo, a expressão “desse trabalho” refere-se ao Programa Nacional de Transparência Pública. D No segundo parágrafo, o pronome “Ela” retoma “gestão estratégica governamental”. E No quarto parágrafo, a expressão “essa posição” refere-se à ideia de obtenção de um nível de transparência entre 95% e 100%.$q$,$q$A respeito dos mecanismos de coesão empregados no texto CG1A1, assinale a opção correta. A No último parágrafo, o trecho ‘Ao contrário de outras tecnologias’ estabelece uma relação de alternância entre as características da IA e as das demais tecnologias. B No trecho entre aspas no quinto parágrafo, a expressão ‘Por isso’ introduz uma conclusão. C No quarto parágrafo, a expressão “desse trabalho” refere-se ao Programa Nacional de Transparência Pública. D No segundo parágrafo, o pronome “Ela” retoma “gestão estratégica governamental”. E No quarto parágrafo, a expressão “essa posição” refere-se à ideia de obtenção de um nível de transparência entre 95% e 100%.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,4,$q$Língua Portuguesa$q$,$q$Assinale a opção em que o vocábulo apresentado está empregado como verbo no texto CG1A1. A “traz” (último parágrafo) B “transformação” (primeiro parágrafo) C “trabalho” (segundo parágrafo) D “lugar” (quarto parágrafo) E “lançamento” (primeiro parágrafo)$q$,$q$Assinale a opção em que o vocábulo apresentado está empregado como verbo no texto CG1A1. A “traz” (último parágrafo) B “transformação” (primeiro parágrafo) C “trabalho” (segundo parágrafo) D “lugar” (quarto parágrafo) E “lançamento” (primeiro parágrafo)$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,5,$q$Língua Portuguesa$q$,$q$No período “Ela surgiu da necessidade de simplificar a relação do poder público com a sociedade, e a IA foi escolhida por sua capacidade de adaptação com base em novos treinamentos.” (segundo parágrafo do texto CG1A1), o emprego da vírgula logo após “sociedade” justifica-se pela finalidade de A indicar a supressão de uma palavra. B sinalizar uma enumeração de termos que exercem a mesma função sintática. C isolar uma oração que funciona como aposto. D marcar uma relação de oposição entre a primeira e a última orações do período. E separar orações cujos sujeitos são distintos.$q$,$q$No período “Ela surgiu da necessidade de simplificar a relação do poder público com a sociedade, e a IA foi escolhida por sua capacidade de adaptação com base em novos treinamentos.” (segundo parágrafo do texto CG1A1), o emprego da vírgula logo após “sociedade” justifica-se pela finalidade de A indicar a supressão de uma palavra. B sinalizar uma enumeração de termos que exercem a mesma função sintática. C isolar uma oração que funciona como aposto. D marcar uma relação de oposição entre a primeira e a última orações do período. E separar orações cujos sujeitos são distintos.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,6,$q$Língua Portuguesa$q$,$q$Em relação ao período “Para alcançar essa posição, é necessário obter um nível de transparência entre 95% e 100%, e Rondônia atingiu 99,29%.” (quarto parágrafo do texto CG1A1), julgue os itens subsequentes. I O trecho “Para alcançar essa posição” expressa uma finalidade relacionada apenas ao conteúdo apresentado na oração imediatamente subsequente no período. II A transposição do trecho “Para alcançar essa posição” para o final do período, desde que feitos os devidos ajustes de maiúsculas e minúsculas, não comprometeria a correção gramatical nem a coerência textual. III A oração “Rondônia atingiu 99,29%” não se subordina sintaticamente à oração imediatamente anterior, mas elas se articulam semanticamente. Assinale a opção correta. A Nenhum item está certo. B Apenas o item I está certo. C Apenas o item II está certo. D Apenas os itens I e III estão certos. E Apenas os itens II e III estão certos.$q$,$q$Em relação ao período “Para alcançar essa posição, é necessário obter um nível de transparência entre 95% e 100%, e Rondônia atingiu 99,29%.” (quarto parágrafo do texto CG1A1), julgue os itens subsequentes. I O trecho “Para alcançar essa posição” expressa uma finalidade relacionada apenas ao conteúdo apresentado na oração imediatamente subsequente no período. II A transposição do trecho “Para alcançar essa posição” para o final do período, desde que feitos os devidos ajustes de maiúsculas e minúsculas, não comprometeria a correção gramatical nem a coerência textual. III A oração “Rondônia atingiu 99,29%” não se subordina sintaticamente à oração imediatamente anterior, mas elas se articulam semanticamente. Assinale a opção correta. A Nenhum item está certo. B Apenas o item I está certo. C Apenas o item II está certo. D Apenas os itens I e III estão certos. E Apenas os itens II e III estão certos.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,7,$q$Língua Portuguesa$q$,$q$Cada uma das opções a seguir apresenta uma proposta de reescrita para o período ‘Apenas acompanhar e replicar tendências não é suficiente para contribuir para a modernização de serviços.’ (quinto parágrafo do texto CG1A1). Assinale a opção em que a proposta de reescrita apresentada mantém a correção gramatical e a coerência do texto. A Acompanhar e replicar tendências apenas não são suficientes para contribuir com a modernização de serviços. B Somente acompanhar tendências e replicá-las não são suficientes para contribuir para modernização dos serviços. C Apenas acompanhar e replicar tendências é insuficiente em contribuir para a modernização dos serviços. D Somente acompanhar e reproduzir tendências não basta para contribuir para a modernização dos serviços. E Apenas o acompanhamento e a replicação de tendências não são suficientes de contribuírem para a modernização dos serviços.$q$,$q$Cada uma das opções a seguir apresenta uma proposta de reescrita para o período ‘Apenas acompanhar e replicar tendências não é suficiente para contribuir para a modernização de serviços.’ (quinto parágrafo do texto CG1A1). Assinale a opção em que a proposta de reescrita apresentada mantém a correção gramatical e a coerência do texto. A Acompanhar e replicar tendências apenas não são suficientes para contribuir com a modernização de serviços. B Somente acompanhar tendências e replicá-las não são suficientes para contribuir para modernização dos serviços. C Apenas acompanhar e replicar tendências é insuficiente em contribuir para a modernização dos serviços. D Somente acompanhar e reproduzir tendências não basta para contribuir para a modernização dos serviços. E Apenas o acompanhamento e a replicação de tendências não são suficientes de contribuírem para a modernização dos serviços.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,8,$q$Língua Portuguesa$q$,$q$Cada uma das próximas opções apresenta um trecho do texto CG1A1 seguido de uma proposta de reescrita. Assinale a opção em que reescrita proposta está gramaticalmente correta, considerando as relações de regência e o emprego do sinal indicativo de crase. A ‘a IA tem a capacidade de aprender e se adaptar continuamente’ (último parágrafo): a IA tem capacidade de aprendizagem e adaptação contínua à novas situações B “Com o objetivo de promover a transformação digital e atender diretamente a população” (primeiro parágrafo): Com o objetivo de promover a transformação digital e de prestar atendimento direto à população C ‘Esses benefícios podem se converter em sistemas de atendimento ao cidadão e ferramentas de análise para políticas públicas’ (último parágrafo): Esses benefícios podem se converter em sistemas destinados à atender o cidadão e em ferramentas de análise às políticas públicas D “Ela surgiu da necessidade de simplificar a relação do poder público com a sociedade” (segundo parágrafo): Ela surgiu devido à necessidade de simplificar a relação do poder público à sociedade E “a Clara representa um avanço para o estado” (terceiro parágrafo): a Clara representa um avanço à esse estado$q$,$q$Cada uma das próximas opções apresenta um trecho do texto CG1A1 seguido de uma proposta de reescrita. Assinale a opção em que reescrita proposta está gramaticalmente correta, considerando as relações de regência e o emprego do sinal indicativo de crase. A ‘a IA tem a capacidade de aprender e se adaptar continuamente’ (último parágrafo): a IA tem capacidade de aprendizagem e adaptação contínua à novas situações B “Com o objetivo de promover a transformação digital e atender diretamente a população” (primeiro parágrafo): Com o objetivo de promover a transformação digital e de prestar atendimento direto à população C ‘Esses benefícios podem se converter em sistemas de atendimento ao cidadão e ferramentas de análise para políticas públicas’ (último parágrafo): Esses benefícios podem se converter em sistemas destinados à atender o cidadão e em ferramentas de análise às políticas públicas D “Ela surgiu da necessidade de simplificar a relação do poder público com a sociedade” (segundo parágrafo): Ela surgiu devido à necessidade de simplificar a relação do poder público à sociedade E “a Clara representa um avanço para o estado” (terceiro parágrafo): a Clara representa um avanço à esse estado$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,9,$q$Língua Portuguesa$q$,$q$No que se refere às relações entre termos no texto CG1A1, julgue os itens subsequentes. I No trecho “a IA foi escolhida por sua capacidade de adaptação com base em novos treinamentos” (final do segundo parágrafo), o segmento “com base em novos treinamentos” modifica o sentido do termo “adaptação”, de tal forma que a substituição de “com base” por baseada manteria o sentido do texto. II No trecho “A Clara é fruto da continuidade desse trabalho e do compromisso do estado com a transformação digital” (final do quarto parágrafo), os segmentos “desse trabalho” e “do compromisso” complementam o sentido do termo “continuidade”, exercendo a mesma função sintática. III No trecho ‘a IA tem a capacidade de aprender e se adaptar continuamente’ (último parágrafo), o termo ‘continuamente’ modifica o sentido apenas do verbo ‘adaptar’, expressando circunstância de intensidade. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$No que se refere às relações entre termos no texto CG1A1, julgue os itens subsequentes. I No trecho “a IA foi escolhida por sua capacidade de adaptação com base em novos treinamentos” (final do segundo parágrafo), o segmento “com base em novos treinamentos” modifica o sentido do termo “adaptação”, de tal forma que a substituição de “com base” por baseada manteria o sentido do texto. II No trecho “A Clara é fruto da continuidade desse trabalho e do compromisso do estado com a transformação digital” (final do quarto parágrafo), os segmentos “desse trabalho” e “do compromisso” complementam o sentido do termo “continuidade”, exercendo a mesma função sintática. III No trecho ‘a IA tem a capacidade de aprender e se adaptar continuamente’ (último parágrafo), o termo ‘continuamente’ modifica o sentido apenas do verbo ‘adaptar’, expressando circunstância de intensidade. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,10,$q$Raciocínio Lógico-Matemático$q$,$q$Aos poucos, Rondônia firma-se como um destino para turistas de outros países interessados em aventuras e pesca esportiva. No biênio 2024-2025, o número total de turistas americanos, portugueses e espanhóis que visitaram Rondônia foi igual a 5.640. Sabe-se que o número de turistas americanos adicionado a três vezes o número de turistas espanhóis é igual a 4.200 e que a diferença entre o número de turistas portugueses e o número de turistas americanos supera o número de turistas espanhóis em exatos 1.120. Com base nessas informações, é correto afirmar que, no referido biênio, A o número de turistas espanhóis foi inferior a 936. B o número de turistas americanos superou o número de turistas portugueses e espanhóis. C o número de turistas espanhóis foi superior a 25% do número de turistas portugueses. D o número de turistas americanos foi superior a 1.920. E o número de turistas portugueses foi inferior à metade do número de turistas americanos.$q$,$q$Aos poucos, Rondônia firma-se como um destino para turistas de outros países interessados em aventuras e pesca esportiva. No biênio 2024-2025, o número total de turistas americanos, portugueses e espanhóis que visitaram Rondônia foi igual a 5.640. Sabe-se que o número de turistas americanos adicionado a três vezes o número de turistas espanhóis é igual a 4.200 e que a diferença entre o número de turistas portugueses e o número de turistas americanos supera o número de turistas espanhóis em exatos 1.120. Com base nessas informações, é correto afirmar que, no referido biênio, A o número de turistas espanhóis foi inferior a 936. B o número de turistas americanos superou o número de turistas portugueses e espanhóis. C o número de turistas espanhóis foi superior a 25% do número de turistas portugueses. D o número de turistas americanos foi superior a 1.920. E o número de turistas portugueses foi inferior à metade do número de turistas americanos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,11,$q$Raciocínio Lógico-Matemático$q$,$q$Uma pesquisa feita com 1.040 visitantes do tradicional Mercado Cultural de Porto Velho revelou quais foram suas escolhas para o almoço durante o final de semana. A tabela a seguir apresenta o resultado da compilação das 1.040 fichas produzidas pelos pesquisadores. comida típica: pirarucu Rondon - homens 150, mulheres 120; caldeirada de peixe - homens 100, mulheres 110; mojica de peixe - homens 80, mulheres 90; pirarucu de casaca - homens 180, mulheres 210; TOTAL - homens 510, mulheres 530. Nessa situação hipotética, se uma das 1.040 pessoas visitantes for selecionada ao acaso, a probabilidade de ela ser mulher ou de ser alguém que almoçou pirarucu de casaca será A inferior a 0,75 e superior a 0,71. B inferior a 0,70 e superior a 0,65. C inferior a 0,64 e superior a 0,60. D inferior a 0,59 e superior a 0,55. E inferior a 0,54 e superior a 0,51.$q$,$q$Uma pesquisa feita com 1.040 visitantes do tradicional Mercado Cultural de Porto Velho revelou quais foram suas escolhas para o almoço durante o final de semana. A tabela a seguir apresenta o resultado da compilação das 1.040 fichas produzidas pelos pesquisadores. comida típica: pirarucu Rondon - homens 150, mulheres 120; caldeirada de peixe - homens 100, mulheres 110; mojica de peixe - homens 80, mulheres 90; pirarucu de casaca - homens 180, mulheres 210; TOTAL - homens 510, mulheres 530. Nessa situação hipotética, se uma das 1.040 pessoas visitantes for selecionada ao acaso, a probabilidade de ela ser mulher ou de ser alguém que almoçou pirarucu de casaca será A inferior a 0,75 e superior a 0,71. B inferior a 0,70 e superior a 0,65. C inferior a 0,64 e superior a 0,60. D inferior a 0,59 e superior a 0,55. E inferior a 0,54 e superior a 0,51.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,12,$q$Raciocínio Lógico-Matemático$q$,$q$Rondônia tem obtido números importantes no combate ao desmatamento e a queimadas no estado. Uma consequência imediata é a melhoria na qualidade do ar nos períodos mais secos do ano. A função C(T) a seguir representa as medições feitas por uma estação de monitoramento da concentração, em µg/m3, de partículas finas de fuligem na atmosfera em determinado tempo T, em que T pertence ao intervalo [0, 24]. C(T) = 100 - (2/5)T² + (72/5)T. De acordo com a função apresentada, a concentração máxima de partículas finas de fuligem na atmosfera no referido período foi A superior a 220 µg/m3. B inferior ou igual a 220 µg/m3 e superior a 204 µg/m3. C inferior ou igual a 204 µg/m3 e superior a 190 µg/m3. D inferior ou igual a 190 µg/m3 e superior a 172 µg/m3. E inferior ou igual a 172 µg/m3.$q$,$q$Rondônia tem obtido números importantes no combate ao desmatamento e a queimadas no estado. Uma consequência imediata é a melhoria na qualidade do ar nos períodos mais secos do ano. A função C(T) a seguir representa as medições feitas por uma estação de monitoramento da concentração, em µg/m3, de partículas finas de fuligem na atmosfera em determinado tempo T, em que T pertence ao intervalo [0, 24]. C(T) = 100 - (2/5)T² + (72/5)T. De acordo com a função apresentada, a concentração máxima de partículas finas de fuligem na atmosfera no referido período foi A superior a 220 µg/m3. B inferior ou igual a 220 µg/m3 e superior a 204 µg/m3. C inferior ou igual a 204 µg/m3 e superior a 190 µg/m3. D inferior ou igual a 190 µg/m3 e superior a 172 µg/m3. E inferior ou igual a 172 µg/m3.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,13,$q$Direito Administrativo$q$,$q$Considerando as finalidades do controle interno e sua relação com o controle externo, assinale a opção correta. A O controle interno é exercido de forma exclusiva pelos órgãos especializados que compõem a estrutura central do sistema de controle de cada Poder, sendo vedada aos agentes públicos que exercem funções finalísticas a prática de atos de autocontrole administrativo. B Entre as finalidades constitucionais do controle interno inclui-se a de apoiar o controle externo no exercício de sua missão institucional, o que estabelece uma relação de subordinação hierárquica do órgão de controle interno para com o tribunal de contas. C Os cidadãos são partes ilegítimas para denunciar irregularidades perante o TCU, sendo tal prerrogativa exclusiva dos partidos políticos, das associações, dos sindicatos e dos órgãos integrantes do sistema de controle interno. D A fiscalização contábil, financeira e orçamentária do município será exercida pelo controle externo da câmara municipal com auxílio dos tribunais de contas dos municípios ou conselhos de contas municipais, se houver, sendo permitida a criação de novos órgãos de controle municipal pelo Poder Legislativo local. E É competência do sistema de controle interno de cada Poder comprovar a legalidade da gestão orçamentária, financeira e patrimonial nos órgãos e nas entidades da administração federal bem como avaliar os resultados quanto à eficácia e eficiência.$q$,$q$Considerando as finalidades do controle interno e sua relação com o controle externo, assinale a opção correta. A O controle interno é exercido de forma exclusiva pelos órgãos especializados que compõem a estrutura central do sistema de controle de cada Poder, sendo vedada aos agentes públicos que exercem funções finalísticas a prática de atos de autocontrole administrativo. B Entre as finalidades constitucionais do controle interno inclui-se a de apoiar o controle externo no exercício de sua missão institucional, o que estabelece uma relação de subordinação hierárquica do órgão de controle interno para com o tribunal de contas. C Os cidadãos são partes ilegítimas para denunciar irregularidades perante o TCU, sendo tal prerrogativa exclusiva dos partidos políticos, das associações, dos sindicatos e dos órgãos integrantes do sistema de controle interno. D A fiscalização contábil, financeira e orçamentária do município será exercida pelo controle externo da câmara municipal com auxílio dos tribunais de contas dos municípios ou conselhos de contas municipais, se houver, sendo permitida a criação de novos órgãos de controle municipal pelo Poder Legislativo local. E É competência do sistema de controle interno de cada Poder comprovar a legalidade da gestão orçamentária, financeira e patrimonial nos órgãos e nas entidades da administração federal bem como avaliar os resultados quanto à eficácia e eficiência.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,14,$q$Direito Administrativo$q$,$q$No que concerne ao controle exercido pelo TCU, assinale a opção correta. A O TCU tem competência constitucional para sustar diretamente a execução de contratos administrativos e de atos administrativos do Poder Executivo que apresentem indícios insanáveis de ilegalidade. B O Poder Judiciário pode anular decisões do TCU quando identificar ilegalidade ou ilegitimidade, mas não pode adentrar no mérito técnico das avaliações de eficiência realizadas pela corte de contas, sob pena de violação ao princípio da separação dos Poderes. C Ao tomarem conhecimento de irregularidade ou ilegalidade, os responsáveis pelo controle interno deverão informá-la ao TCU, sob pena de responsabilidade solidária e crime de prevaricação. D As decisões do TCU de que resulte imputação de débito ou multa possuem eficácia de título executivo judicial, prescindindo de ação de execução perante o Poder Judiciário. E O controle externo, a cargo do Congresso Nacional, será exercido com o auxílio do TCU, ao qual compete julgar anualmente as contas prestadas pelo presidente da República.$q$,$q$No que concerne ao controle exercido pelo TCU, assinale a opção correta. A O TCU tem competência constitucional para sustar diretamente a execução de contratos administrativos e de atos administrativos do Poder Executivo que apresentem indícios insanáveis de ilegalidade. B O Poder Judiciário pode anular decisões do TCU quando identificar ilegalidade ou ilegitimidade, mas não pode adentrar no mérito técnico das avaliações de eficiência realizadas pela corte de contas, sob pena de violação ao princípio da separação dos Poderes. C Ao tomarem conhecimento de irregularidade ou ilegalidade, os responsáveis pelo controle interno deverão informá-la ao TCU, sob pena de responsabilidade solidária e crime de prevaricação. D As decisões do TCU de que resulte imputação de débito ou multa possuem eficácia de título executivo judicial, prescindindo de ação de execução perante o Poder Judiciário. E O controle externo, a cargo do Congresso Nacional, será exercido com o auxílio do TCU, ao qual compete julgar anualmente as contas prestadas pelo presidente da República.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,15,$q$Direito Administrativo$q$,$q$No que diz respeito aos sistemas de controle jurisdicional da administração pública, especificamente no que se refere ao sistema do contencioso administrativo e ao sistema da jurisdição una, assinale a opção correta. A A Constituição Federal de 1988 mitigou o sistema de jurisdição una ao prever que o esgotamento da via administrativa é condição geral e obrigatória para o ajuizamento de qualquer ação judicial que envolva litígios com o poder público. B No sistema do contencioso administrativo, há uma dualidade de jurisdições, competindo a um ramo especializado da própria estrutura administrativa do Estado dar a palavra final sobre a legalidade dos atos da administração pública. C No modelo de jurisdição una, o Poder Judiciário detém o monopólio da função jurisdicional, o que impede a administração pública de praticar atos de autotutela e de anular seus próprios atos ilegais. D O Brasil adota, desde a Proclamação da República, o sistema do contencioso administrativo, de modo que as decisões dos tribunais administrativos possuem força de coisa julgada e são impassíveis de revisão pelo Poder Judiciário. E No sistema da jurisdição una, adotado pelo ordenamento jurídico brasileiro, a existência de instâncias administrativas prévias de conciliação ou julgamento é considerada inconstitucional por violar o princípio do livre acesso à justiça.$q$,$q$No que diz respeito aos sistemas de controle jurisdicional da administração pública, especificamente no que se refere ao sistema do contencioso administrativo e ao sistema da jurisdição una, assinale a opção correta. A A Constituição Federal de 1988 mitigou o sistema de jurisdição una ao prever que o esgotamento da via administrativa é condição geral e obrigatória para o ajuizamento de qualquer ação judicial que envolva litígios com o poder público. B No sistema do contencioso administrativo, há uma dualidade de jurisdições, competindo a um ramo especializado da própria estrutura administrativa do Estado dar a palavra final sobre a legalidade dos atos da administração pública. C No modelo de jurisdição una, o Poder Judiciário detém o monopólio da função jurisdicional, o que impede a administração pública de praticar atos de autotutela e de anular seus próprios atos ilegais. D O Brasil adota, desde a Proclamação da República, o sistema do contencioso administrativo, de modo que as decisões dos tribunais administrativos possuem força de coisa julgada e são impassíveis de revisão pelo Poder Judiciário. E No sistema da jurisdição una, adotado pelo ordenamento jurídico brasileiro, a existência de instâncias administrativas prévias de conciliação ou julgamento é considerada inconstitucional por violar o princípio do livre acesso à justiça.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,16,$q$Direito Administrativo$q$,$q$Assinale a opção correta em relação ao controle parlamentar e ao controle pelos tribunais de contas. A Em decorrência do princípio da simetria, os tribunais de contas estaduais detêm competência autônoma para sustar a execução de contratos administrativos e convênios firmados pelo Poder Executivo local sempre que constatado sobrepreço insanável. B A competência do Congresso Nacional para sustar os atos normativos do Poder Executivo que exorbitem do poder regulamentar é aplicável tanto aos decretos de natureza regulamentar quanto aos decretos autônomos que invadam a reserva de lei formal. C No exercício de suas atribuições institucionais de apuração de fato determinado, as comissões parlamentares de inquérito detêm competência para determinar a quebra de sigilo bancário e fiscal dos investigados, bem como para decretar a indisponibilidade de seus bens como medida cautelar. D O comparecimento de ministro de Estado perante a Câmara dos Deputados ou o Senado Federal, para prestar informações sobre assunto previamente determinado, é ato de natureza discricionária e cortesia institucional, não se exigindo justificativa formal para sua eventual ausência. E O ato normativo do Poder Executivo que exorbite dos limites da delegação legislativa ou do poder regulamentar poderá ser diretamente anulado pelo Congresso Nacional, o que gerará efeitos retroativos (ex tunc) sobre as relações jurídicas já constituídas.$q$,$q$Assinale a opção correta em relação ao controle parlamentar e ao controle pelos tribunais de contas. A Em decorrência do princípio da simetria, os tribunais de contas estaduais detêm competência autônoma para sustar a execução de contratos administrativos e convênios firmados pelo Poder Executivo local sempre que constatado sobrepreço insanável. B A competência do Congresso Nacional para sustar os atos normativos do Poder Executivo que exorbitem do poder regulamentar é aplicável tanto aos decretos de natureza regulamentar quanto aos decretos autônomos que invadam a reserva de lei formal. C No exercício de suas atribuições institucionais de apuração de fato determinado, as comissões parlamentares de inquérito detêm competência para determinar a quebra de sigilo bancário e fiscal dos investigados, bem como para decretar a indisponibilidade de seus bens como medida cautelar. D O comparecimento de ministro de Estado perante a Câmara dos Deputados ou o Senado Federal, para prestar informações sobre assunto previamente determinado, é ato de natureza discricionária e cortesia institucional, não se exigindo justificativa formal para sua eventual ausência. E O ato normativo do Poder Executivo que exorbite dos limites da delegação legislativa ou do poder regulamentar poderá ser diretamente anulado pelo Congresso Nacional, o que gerará efeitos retroativos (ex tunc) sobre as relações jurídicas já constituídas.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,17,$q$Administração Geral$q$,$q$Considerando as características fundamentais das abordagens clássica, burocrática e sistêmica da administração, assinale a opção correta. A A teoria da burocracia e a teoria clássica convergem estritamente no que diz respeito à homogeneidade de tarefas, visto que ambas fundamentam seus modelos na substituição da autoridade legal-racional pela liderança carismática dos chefes de seção. B A abordagem clássica, que engloba a administração científica de Taylor e a teoria clássica de Fayol, concebe a organização como um sistema aberto, priorizando a adaptabilidade da estrutura formal às demandas e pressões do mercado. C Conforme a abordagem burocrática de Max Weber, a impessoalidade e a profissionalização das relações garantem a máxima eficiência técnica, o que impede a ocorrência de disfunções organizacionais, tais como o apego exagerado aos regulamentos e a resistência a mudanças. D A abordagem sistêmica introduziu a noção de que as organizações são sistemas abertos em constante intercâmbio com o ambiente, defendendo o princípio da entropia positiva como o mecanismo pelo qual a empresa absorve energia do meio externo para garantir sua sobrevivência e crescimento. E Ao contrário da abordagem clássica, que foca as tarefas e a estrutura interna de maneira isolada, a abordagem sistêmica analisa a organização a partir da interdependência de seus componentes internos e de sua interação dinâmica com o ambiente macroeconômico e social.$q$,$q$Considerando as características fundamentais das abordagens clássica, burocrática e sistêmica da administração, assinale a opção correta. A A teoria da burocracia e a teoria clássica convergem estritamente no que diz respeito à homogeneidade de tarefas, visto que ambas fundamentam seus modelos na substituição da autoridade legal-racional pela liderança carismática dos chefes de seção. B A abordagem clássica, que engloba a administração científica de Taylor e a teoria clássica de Fayol, concebe a organização como um sistema aberto, priorizando a adaptabilidade da estrutura formal às demandas e pressões do mercado. C Conforme a abordagem burocrática de Max Weber, a impessoalidade e a profissionalização das relações garantem a máxima eficiência técnica, o que impede a ocorrência de disfunções organizacionais, tais como o apego exagerado aos regulamentos e a resistência a mudanças. D A abordagem sistêmica introduziu a noção de que as organizações são sistemas abertos em constante intercâmbio com o ambiente, defendendo o princípio da entropia positiva como o mecanismo pelo qual a empresa absorve energia do meio externo para garantir sua sobrevivência e crescimento. E Ao contrário da abordagem clássica, que foca as tarefas e a estrutura interna de maneira isolada, a abordagem sistêmica analisa a organização a partir da interdependência de seus componentes internos e de sua interação dinâmica com o ambiente macroeconômico e social.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,18,$q$Administração Geral$q$,$q$A respeito das características, dos desdobramentos e da aplicação das funções de planejamento, organização, direção e controle, assinale a opção correta. A A função de direção está essencialmente ligada à condução e à coordenação do elemento humano na organização, envolvendo processos de liderança, motivação e comunicação, manifestando-se em todos os níveis hierárquicos do processo administrativo. B O controle preventivo é aquele exercido simultaneamente à execução das atividades organizacionais, de modo a permitir que o gestor aplique correções de rumo em tempo real, antes que a tarefa seja totalmente concluída. C O estabelecimento de padrões de desempenho e a mensuração de resultados são etapas facultativas da função de controle, cuja atribuição principal consiste na aplicação de sanções administrativas aos colaboradores com baixa produtividade. D O planejamento estratégico, por situar-se no nível institucional da organização, tem forte orientação para o curto prazo, detalhando analiticamente as tarefas e operações necessárias para a execução das metas cotidianas da empresa. E A função de organização ocupa-se do arranjo físico das instalações e da distribuição espacial dos equipamentos e móveis nos setores de produção, sem abranger a atribuição de responsabilidades ou a divisão do trabalho.$q$,$q$A respeito das características, dos desdobramentos e da aplicação das funções de planejamento, organização, direção e controle, assinale a opção correta. A A função de direção está essencialmente ligada à condução e à coordenação do elemento humano na organização, envolvendo processos de liderança, motivação e comunicação, manifestando-se em todos os níveis hierárquicos do processo administrativo. B O controle preventivo é aquele exercido simultaneamente à execução das atividades organizacionais, de modo a permitir que o gestor aplique correções de rumo em tempo real, antes que a tarefa seja totalmente concluída. C O estabelecimento de padrões de desempenho e a mensuração de resultados são etapas facultativas da função de controle, cuja atribuição principal consiste na aplicação de sanções administrativas aos colaboradores com baixa produtividade. D O planejamento estratégico, por situar-se no nível institucional da organização, tem forte orientação para o curto prazo, detalhando analiticamente as tarefas e operações necessárias para a execução das metas cotidianas da empresa. E A função de organização ocupa-se do arranjo físico das instalações e da distribuição espacial dos equipamentos e móveis nos setores de produção, sem abranger a atribuição de responsabilidades ou a divisão do trabalho.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,19,$q$Administração Geral$q$,$q$No que diz respeito aos constructos de motivação, liderança e desempenho nas relações entre indivíduo e organização, assinale a opção correta. A A teoria X de Douglas McGregor assume uma visão otimista e humanista do comportamento humano, sustentando que os indivíduos possuem motivação intrínseca, buscam responsabilidades e direcionam o seu desempenho às metas organizacionais de forma autônoma. B De acordo com a teoria da expectativa formulada por Victor Vroom, a motivação de um indivíduo para agir é o produto de três fatores determinantes: a expectativa (relação esforço-desempenho), a instrumentalidade (relação desempenho-recompensa) e a valência (o valor atribuído à recompensa). C Segundo a teoria dos dois fatores de Frederick Herzberg, os fatores higiênicos, como salário, benefícios e condições de trabalho, quando excelentes, são capazes de gerar alta motivação e engajamento sustentável de longo prazo nos colaboradores. D O contrato psicológico de trabalho circunscreve-se às cláusulas formais e pecuniárias registradas na carteira de trabalho ou no estatuto do servidor, as quais delimitam as metas de desempenho que o indivíduo deve atingir obrigatoriamente. E As teorias contingenciais da liderança, como o modelo de Fiedler e a teoria caminho-meta, defendem que existe um estilo de liderança único, focado ou em pessoas ou em tarefas, e universalmente eficaz, independentemente das variáveis ambientais ou da maturidade dos liderados.$q$,$q$No que diz respeito aos constructos de motivação, liderança e desempenho nas relações entre indivíduo e organização, assinale a opção correta. A A teoria X de Douglas McGregor assume uma visão otimista e humanista do comportamento humano, sustentando que os indivíduos possuem motivação intrínseca, buscam responsabilidades e direcionam o seu desempenho às metas organizacionais de forma autônoma. B De acordo com a teoria da expectativa formulada por Victor Vroom, a motivação de um indivíduo para agir é o produto de três fatores determinantes: a expectativa (relação esforço-desempenho), a instrumentalidade (relação desempenho-recompensa) e a valência (o valor atribuído à recompensa). C Segundo a teoria dos dois fatores de Frederick Herzberg, os fatores higiênicos, como salário, benefícios e condições de trabalho, quando excelentes, são capazes de gerar alta motivação e engajamento sustentável de longo prazo nos colaboradores. D O contrato psicológico de trabalho circunscreve-se às cláusulas formais e pecuniárias registradas na carteira de trabalho ou no estatuto do servidor, as quais delimitam as metas de desempenho que o indivíduo deve atingir obrigatoriamente. E As teorias contingenciais da liderança, como o modelo de Fiedler e a teoria caminho-meta, defendem que existe um estilo de liderança único, focado ou em pessoas ou em tarefas, e universalmente eficaz, independentemente das variáveis ambientais ou da maturidade dos liderados.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,20,$q$Administração Geral$q$,$q$No que diz respeito a metodologias de avaliação e a indicadores de viabilidade econômico-financeira de projetos, assinale a opção correta. A Na fase de elaboração do projeto, a análise de sensibilidade deve ser evitada, por introduzir variáveis subjetivas que reduzem a precisão dos dados do escopo e aumentam artificialmente o risco estimado da proposta. B Na análise de custo-benefício de projetos sociais ou públicos, tanto os custos quanto os benefícios devem ser mensurados e expressos em termos monetários, o que a diferencia essencialmente da análise de custo-efetividade. C O indicador de payback descontado tem a desvantagem analítica de desconsiderar o custo de capital da organização, uma vez que utiliza fluxos de caixa nominais, sem aplicação de uma taxa de desconto para trazer os valores ao momento presente. D O valor presente líquido (VPL) de um projeto é o cálculo do tempo necessário para que o fluxo de caixa acumulado iguale-se ao investimento inicial, sendo considerado um método que ignora o valor do dinheiro no tempo. E A taxa interna de retorno (TIR) representa a taxa de desconto que iguala o valor presente líquido (VPL) do projeto a zero, de maneira tal que um projeto é considerado economicamente viável quando sua TIR é menor que a taxa mínima de atratividade (TMA) estipulada pelos investidores.$q$,$q$No que diz respeito a metodologias de avaliação e a indicadores de viabilidade econômico-financeira de projetos, assinale a opção correta. A Na fase de elaboração do projeto, a análise de sensibilidade deve ser evitada, por introduzir variáveis subjetivas que reduzem a precisão dos dados do escopo e aumentam artificialmente o risco estimado da proposta. B Na análise de custo-benefício de projetos sociais ou públicos, tanto os custos quanto os benefícios devem ser mensurados e expressos em termos monetários, o que a diferencia essencialmente da análise de custo-efetividade. C O indicador de payback descontado tem a desvantagem analítica de desconsiderar o custo de capital da organização, uma vez que utiliza fluxos de caixa nominais, sem aplicação de uma taxa de desconto para trazer os valores ao momento presente. D O valor presente líquido (VPL) de um projeto é o cálculo do tempo necessário para que o fluxo de caixa acumulado iguale-se ao investimento inicial, sendo considerado um método que ignora o valor do dinheiro no tempo. E A taxa interna de retorno (TIR) representa a taxa de desconto que iguala o valor presente líquido (VPL) do projeto a zero, de maneira tal que um projeto é considerado economicamente viável quando sua TIR é menor que a taxa mínima de atratividade (TMA) estipulada pelos investidores.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,21,$q$Direito Constitucional$q$,$q$Em relação às competências constitucionais do Congresso Nacional, da Câmara dos Deputados e do Senado Federal, assinale a opção correta. A Compete privativamente à Câmara dos Deputados, além de autorizar por dois terços a instauração de processo contra o presidente da República, proceder à tomada de contas do chefe de Estado quando não apresentadas ao Congresso Nacional dentro de 60 dias após o encerramento da sessão legislativa. B As mesas da Câmara dos Deputados e do Senado Federal podem encaminhar pedido escrito de informações a ministros de Estado, importando em crime comum a recusa ou o não atendimento ao pedido no prazo de 30 dias, bem como a prestação de informações falsas. C Compete privativamente ao Senado Federal aprovar previamente, por voto secreto, após arguição pública, a escolha de todos os ministros do TCU, independentemente da origem da indicação. D Compete privativamente ao Senado Federal aprovar, por maioria absoluta e por voto secreto, a exoneração de ofício do procurador-geral da República antes do término de seu mandato. E É competência exclusiva do Congresso Nacional, dispensada a sanção presidencial, aprovar previamente a alienação ou a concessão de terras públicas com área superior a 5.000 hectares.$q$,$q$Em relação às competências constitucionais do Congresso Nacional, da Câmara dos Deputados e do Senado Federal, assinale a opção correta. A Compete privativamente à Câmara dos Deputados, além de autorizar por dois terços a instauração de processo contra o presidente da República, proceder à tomada de contas do chefe de Estado quando não apresentadas ao Congresso Nacional dentro de 60 dias após o encerramento da sessão legislativa. B As mesas da Câmara dos Deputados e do Senado Federal podem encaminhar pedido escrito de informações a ministros de Estado, importando em crime comum a recusa ou o não atendimento ao pedido no prazo de 30 dias, bem como a prestação de informações falsas. C Compete privativamente ao Senado Federal aprovar previamente, por voto secreto, após arguição pública, a escolha de todos os ministros do TCU, independentemente da origem da indicação. D Compete privativamente ao Senado Federal aprovar, por maioria absoluta e por voto secreto, a exoneração de ofício do procurador-geral da República antes do término de seu mandato. E É competência exclusiva do Congresso Nacional, dispensada a sanção presidencial, aprovar previamente a alienação ou a concessão de terras públicas com área superior a 5.000 hectares.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,22,$q$Direito Constitucional$q$,$q$Em relação à aplicabilidade e à eficácia das normas constitucionais, segundo a classificação doutrinária tripartite, julgue os seguintes itens. I As normas constitucionais de eficácia contida possuem aplicabilidade direta e imediata desde a promulgação da Constituição Federal, podendo sua eficácia ser reduzida por norma infraconstitucional posterior; enquanto não editada a lei restritiva, o direito assegurado é exercitável em toda a sua extensão. II As normas constitucionais de eficácia plena têm aplicabilidade direta, imediata e integral, admitindo, contudo, restrição pelo legislador infraconstitucional desde que preservado o núcleo essencial do direito assegurado, segundo a classificação tripartite adotada. III As normas constitucionais de eficácia limitada, por dependerem de regulamentação infraconstitucional para a produção de seus efeitos típicos, não produzem qualquer efeito jurídico antes da edição da norma integradora, sendo dotadas de aplicabilidade indireta, mediata e não integral. IV As normas programáticas constituem espécie de normas de eficácia contida, pois, embora produzam efeitos desde a promulgação da Constituição Federal, sua plena eficácia depende da atuação do legislador infraconstitucional para a concretização dos programas e das metas nelas estabelecidos. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas o item IV está certo. D Apenas os itens II e IV estão certos. E Apenas os itens I, II e III estão certos.$q$,$q$Em relação à aplicabilidade e à eficácia das normas constitucionais, segundo a classificação doutrinária tripartite, julgue os seguintes itens. I As normas constitucionais de eficácia contida possuem aplicabilidade direta e imediata desde a promulgação da Constituição Federal, podendo sua eficácia ser reduzida por norma infraconstitucional posterior; enquanto não editada a lei restritiva, o direito assegurado é exercitável em toda a sua extensão. II As normas constitucionais de eficácia plena têm aplicabilidade direta, imediata e integral, admitindo, contudo, restrição pelo legislador infraconstitucional desde que preservado o núcleo essencial do direito assegurado, segundo a classificação tripartite adotada. III As normas constitucionais de eficácia limitada, por dependerem de regulamentação infraconstitucional para a produção de seus efeitos típicos, não produzem qualquer efeito jurídico antes da edição da norma integradora, sendo dotadas de aplicabilidade indireta, mediata e não integral. IV As normas programáticas constituem espécie de normas de eficácia contida, pois, embora produzam efeitos desde a promulgação da Constituição Federal, sua plena eficácia depende da atuação do legislador infraconstitucional para a concretização dos programas e das metas nelas estabelecidos. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas o item IV está certo. D Apenas os itens II e IV estão certos. E Apenas os itens I, II e III estão certos.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,23,$q$Direito Constitucional$q$,$q$O Congresso Nacional aprovou projeto de lei ordinária e o encaminhou ao presidente da República, que o vetou parcialmente no prazo constitucional: suprimiu expressão isolada constante do meio de um parágrafo, tendo mantido intactos artigos, parágrafos, incisos e alíneas. Em relação à parte não vetada, o presidente promulgou e publicou a lei imediatamente, sem aguardar a apreciação do veto pelo Congresso Nacional. Posteriormente, o Congresso Nacional derrubou o veto. O presidente da República, todavia, quedou-se inerte e não promulgou a parte antes vetada no prazo de 48 horas constitucionalmente previsto. Nessa situação hipotética, A a promulgação da parte vetada caberá ao presidente da Câmara dos Deputados e, caso persista a inércia, ao vice-presidente da Câmara dos Deputados. B a inércia presidencial será apreciada em sessão conjunta do Congresso Nacional, em caráter de urgência, podendo o chefe de Estado ser convocado para explicar-se aos presidentes das casas legislativas. C o veto parcial é formalmente inconstitucional por incidir sobre expressão isolada no interior de um parágrafo, o que contraria a exigência de aposição sobre a íntegra do texto consistente no suporte físico das normas. D o veto parcial aposto pelo presidente da República é formalmente válido, pois a Constituição Federal de 1988 não define o que seja unidade normativa para fins de veto, sendo suficiente que o conteúdo suprimido tenha autonomia semântica em relação ao restante do texto. E o veto parcial aposto pelo presidente da República é formalmente válido, pois a exigência constitucional de unidade normativa é satisfeita quando o veto recai sobre conteúdo divisível e autônomo, independentemente de incidir sobre expressão isolada no interior de um parágrafo.$q$,$q$O Congresso Nacional aprovou projeto de lei ordinária e o encaminhou ao presidente da República, que o vetou parcialmente no prazo constitucional: suprimiu expressão isolada constante do meio de um parágrafo, tendo mantido intactos artigos, parágrafos, incisos e alíneas. Em relação à parte não vetada, o presidente promulgou e publicou a lei imediatamente, sem aguardar a apreciação do veto pelo Congresso Nacional. Posteriormente, o Congresso Nacional derrubou o veto. O presidente da República, todavia, quedou-se inerte e não promulgou a parte antes vetada no prazo de 48 horas constitucionalmente previsto. Nessa situação hipotética, A a promulgação da parte vetada caberá ao presidente da Câmara dos Deputados e, caso persista a inércia, ao vice-presidente da Câmara dos Deputados. B a inércia presidencial será apreciada em sessão conjunta do Congresso Nacional, em caráter de urgência, podendo o chefe de Estado ser convocado para explicar-se aos presidentes das casas legislativas. C o veto parcial é formalmente inconstitucional por incidir sobre expressão isolada no interior de um parágrafo, o que contraria a exigência de aposição sobre a íntegra do texto consistente no suporte físico das normas. D o veto parcial aposto pelo presidente da República é formalmente válido, pois a Constituição Federal de 1988 não define o que seja unidade normativa para fins de veto, sendo suficiente que o conteúdo suprimido tenha autonomia semântica em relação ao restante do texto. E o veto parcial aposto pelo presidente da República é formalmente válido, pois a exigência constitucional de unidade normativa é satisfeita quando o veto recai sobre conteúdo divisível e autônomo, independentemente de incidir sobre expressão isolada no interior de um parágrafo.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,24,$q$Direito Administrativo$q$,$q$Com base nas disposições da Lei Complementar municipal n.º 745/2018, que disciplina o processo administrativo no âmbito da administração municipal de Porto Velho, assinale a opção correta. A Caso um parecer obrigatório e não vinculante deixe de ser emitido no prazo fixado, o processo ficará suspenso até a sua apresentação, sem prejuízo do andamento das demais fases que não dependam do parecer, sendo o responsável pela omissão passível de punição disciplinar. B A prioridade de tramitação concedida em razão de doença grave cessa com o falecimento do beneficiado, não se admitindo sua extensão ao cônjuge supérstite ou ao companheiro em união estável, por caracterizar-se como benefício de caráter personalíssimo. C Salvo disposição legal em contrário, o efeito suspensivo ao recurso administrativo somente pode ser conferido pelo superior hierárquico da autoridade que proferiu a decisão, mediante requerimento expresso formulado pelo recorrente. D A aplicação de sanções, assim como a emissão de atos normativos, a decisão de recursos administrativos e as matérias de competência exclusiva do órgão ou da autoridade, constituem matérias que não podem ser objeto de delegação de competência. E A autoridade competente para decidir o recurso pode agravar a situação do recorrente em relação à decisão impugnada, desde que a decisão seja devidamente motivada, sendo desnecessária a prévia cientificação do interessado para formular alegações.$q$,$q$Com base nas disposições da Lei Complementar municipal n.º 745/2018, que disciplina o processo administrativo no âmbito da administração municipal de Porto Velho, assinale a opção correta. A Caso um parecer obrigatório e não vinculante deixe de ser emitido no prazo fixado, o processo ficará suspenso até a sua apresentação, sem prejuízo do andamento das demais fases que não dependam do parecer, sendo o responsável pela omissão passível de punição disciplinar. B A prioridade de tramitação concedida em razão de doença grave cessa com o falecimento do beneficiado, não se admitindo sua extensão ao cônjuge supérstite ou ao companheiro em união estável, por caracterizar-se como benefício de caráter personalíssimo. C Salvo disposição legal em contrário, o efeito suspensivo ao recurso administrativo somente pode ser conferido pelo superior hierárquico da autoridade que proferiu a decisão, mediante requerimento expresso formulado pelo recorrente. D A aplicação de sanções, assim como a emissão de atos normativos, a decisão de recursos administrativos e as matérias de competência exclusiva do órgão ou da autoridade, constituem matérias que não podem ser objeto de delegação de competência. E A autoridade competente para decidir o recurso pode agravar a situação do recorrente em relação à decisão impugnada, desde que a decisão seja devidamente motivada, sendo desnecessária a prévia cientificação do interessado para formular alegações.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,25,$q$Proteção de Dados Pessoais (LGPD)$q$,$q$Uma secretaria municipal contratou empresa privada para realizar, na condição de operadora, o tratamento de dados pessoais de beneficiários de um programa de assistência social. Durante a execução contratual, a empresa processou os dados para finalidade diversa da estabelecida em contrato, sem conhecimento da secretaria, o que causou danos aos beneficiários. Descoberta a irregularidade, a secretaria alegou ter adotado todas as medidas de segurança exigíveis e desconhecer integralmente a conduta da operadora. Considerando a situação hipotética apresentada, assinale a opção correta acerca do regime de responsabilidade e do tratamento de dados pelo poder público de acordo com a Lei Geral de Proteção de Dados Pessoais (LGPD). A A secretaria pode eximir-se da responsabilidade se comprovar que adotou as medidas de segurança exigíveis e que o operador agiu em desconformidade com as instruções lícitas recebidas, hipótese em que o operador se equipara ao controlador e responde objetivamente pelos danos causados aos titulares dos dados. B Os dados tratados pela operadora, ainda que houvessem sido previamente pseudonimizados pela secretaria, continuariam a ser considerados dados pessoais para fins da LGPD. C A secretaria controladora fica totalmente isenta de responsabilidade pelos danos sofridos pelos beneficiários se demonstrar a culpa concorrente destes na ocorrência do evento danoso, independentemente da gravidade da conduta da operadora. D A secretaria poderia ter fundamentado o tratamento de dados na hipótese do legítimo interesse do controlador, previsto na LGPD como base legal aplicável inclusive ao poder público, independentemente da finalidade do tratamento e sem distinção entre agentes de tratamento privados e públicos. E Em razão de sua posição acessória na relação de tratamento de dados, a empresa operadora responde de forma subsidiária pelos danos causados aos titulares, podendo ser acionada apenas após o esgotamento das possibilidades de ressarcimento pela secretaria controladora.$q$,$q$Uma secretaria municipal contratou empresa privada para realizar, na condição de operadora, o tratamento de dados pessoais de beneficiários de um programa de assistência social. Durante a execução contratual, a empresa processou os dados para finalidade diversa da estabelecida em contrato, sem conhecimento da secretaria, o que causou danos aos beneficiários. Descoberta a irregularidade, a secretaria alegou ter adotado todas as medidas de segurança exigíveis e desconhecer integralmente a conduta da operadora. Considerando a situação hipotética apresentada, assinale a opção correta acerca do regime de responsabilidade e do tratamento de dados pelo poder público de acordo com a Lei Geral de Proteção de Dados Pessoais (LGPD). A A secretaria pode eximir-se da responsabilidade se comprovar que adotou as medidas de segurança exigíveis e que o operador agiu em desconformidade com as instruções lícitas recebidas, hipótese em que o operador se equipara ao controlador e responde objetivamente pelos danos causados aos titulares dos dados. B Os dados tratados pela operadora, ainda que houvessem sido previamente pseudonimizados pela secretaria, continuariam a ser considerados dados pessoais para fins da LGPD. C A secretaria controladora fica totalmente isenta de responsabilidade pelos danos sofridos pelos beneficiários se demonstrar a culpa concorrente destes na ocorrência do evento danoso, independentemente da gravidade da conduta da operadora. D A secretaria poderia ter fundamentado o tratamento de dados na hipótese do legítimo interesse do controlador, previsto na LGPD como base legal aplicável inclusive ao poder público, independentemente da finalidade do tratamento e sem distinção entre agentes de tratamento privados e públicos. E Em razão de sua posição acessória na relação de tratamento de dados, a empresa operadora responde de forma subsidiária pelos danos causados aos titulares, podendo ser acionada apenas após o esgotamento das possibilidades de ressarcimento pela secretaria controladora.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,26,$q$Licitações e Contratos$q$,$q$A Controladoria-Geral do Município de Porto Velho instaurou auditoria sobre dois processos licitatórios conduzidos por determinada secretaria municipal. O primeiro processo foi realizado na modalidade pregão com critério de julgamento de menor preço, tendo sido adotado exclusivamente o modo de disputa fechado. O segundo processo foi realizado na modalidade concorrência com critério de julgamento de técnica e preço, tendo sido adotado o modo de disputa aberto. Em ambos os processos, os editais foram publicados apenas no Diário Oficial do município, sem divulgação no Portal Nacional de Contratações Públicas (PNCP), sob a alegação de que esta seria facultativa para os municípios. Em relação aos dois processos mencionados nessa situação hipotética, assinale a opção correta. A O primeiro processo é irregular porque o modo de disputa fechado isolado é vedado quando o critério é o de menor preço; o segundo também é irregular porque o modo aberto é vedado quando o critério é o de técnica e preço; e a omissão de divulgação no PNCP configura irregularidade em ambos, pois a obrigatoriedade recai sobre a divulgação dos atos, sendo facultativa apenas a realização das contratações pelo portal. B O primeiro processo é irregular porque o modo de disputa fechado isolado é vedado quando o critério de julgamento é o de menor preço; o segundo não apresenta irregularidade quanto ao modo de disputa, pois o critério de técnica e preço admite tanto o modo aberto quanto o fechado, a critério motivado da administração pública; e a omissão de divulgação no PNCP configura irregularidade em ambos. C O primeiro processo é irregular porque o modo de disputa fechado isolado é vedado quando o critério é o menor preço; o segundo não apresenta irregularidade quanto ao modo de disputa, pois o modo aberto é o adequado quando o critério é o de técnica e preço; e a omissão de publicação no PNCP não configura irregularidade, pois tanto a publicação dos atos quanto a realização das contratações pelo portal são facultativas para os municípios. D O primeiro processo não apresenta irregularidade, pois o critério de menor preço é adequado ao pregão e o modo fechado é permitido nessa modalidade; o segundo é irregular porque o modo aberto é vedado quando o critério é o de técnica e preço; e a omissão de publicação no PNCP não configura irregularidade, sendo a publicação dos atos facultativa para municípios da mesma forma que a realização das contratações. E O primeiro processo não apresenta irregularidade, pois o critério de menor preço é adequado ao pregão e o modo de disputa fechado isolado é permitido nessa modalidade, desde que o edital justifique a opção; o segundo é irregular, porque o modo aberto é vedado quando o critério é técnica e preço; e a omissão de divulgação no PNCP configura irregularidade em ambos.$q$,$q$A Controladoria-Geral do Município de Porto Velho instaurou auditoria sobre dois processos licitatórios conduzidos por determinada secretaria municipal. O primeiro processo foi realizado na modalidade pregão com critério de julgamento de menor preço, tendo sido adotado exclusivamente o modo de disputa fechado. O segundo processo foi realizado na modalidade concorrência com critério de julgamento de técnica e preço, tendo sido adotado o modo de disputa aberto. Em ambos os processos, os editais foram publicados apenas no Diário Oficial do município, sem divulgação no Portal Nacional de Contratações Públicas (PNCP), sob a alegação de que esta seria facultativa para os municípios. Em relação aos dois processos mencionados nessa situação hipotética, assinale a opção correta. A O primeiro processo é irregular porque o modo de disputa fechado isolado é vedado quando o critério é o de menor preço; o segundo também é irregular porque o modo aberto é vedado quando o critério é o de técnica e preço; e a omissão de divulgação no PNCP configura irregularidade em ambos, pois a obrigatoriedade recai sobre a divulgação dos atos, sendo facultativa apenas a realização das contratações pelo portal. B O primeiro processo é irregular porque o modo de disputa fechado isolado é vedado quando o critério de julgamento é o de menor preço; o segundo não apresenta irregularidade quanto ao modo de disputa, pois o critério de técnica e preço admite tanto o modo aberto quanto o fechado, a critério motivado da administração pública; e a omissão de divulgação no PNCP configura irregularidade em ambos. C O primeiro processo é irregular porque o modo de disputa fechado isolado é vedado quando o critério é o menor preço; o segundo não apresenta irregularidade quanto ao modo de disputa, pois o modo aberto é o adequado quando o critério é o de técnica e preço; e a omissão de publicação no PNCP não configura irregularidade, pois tanto a publicação dos atos quanto a realização das contratações pelo portal são facultativas para os municípios. D O primeiro processo não apresenta irregularidade, pois o critério de menor preço é adequado ao pregão e o modo fechado é permitido nessa modalidade; o segundo é irregular porque o modo aberto é vedado quando o critério é o de técnica e preço; e a omissão de publicação no PNCP não configura irregularidade, sendo a publicação dos atos facultativa para municípios da mesma forma que a realização das contratações. E O primeiro processo não apresenta irregularidade, pois o critério de menor preço é adequado ao pregão e o modo de disputa fechado isolado é permitido nessa modalidade, desde que o edital justifique a opção; o segundo é irregular, porque o modo aberto é vedado quando o critério é técnica e preço; e a omissão de divulgação no PNCP configura irregularidade em ambos.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,27,$q$Tecnologia da Informação$q$,$q$Assinale a opção correta no que se refere a dados estruturados e não estruturados, bem como a coleta, tratamento, armazenamento, integração e recuperação de dados. A Dados não estruturados são mais bem gerenciados quando armazenados em bancos não relacionais ou data lakes, por não seguirem modelo predefinido. B Na consolidação de dados provenientes de múltiplas fontes, a coincidência das identificações das entidades afasta a necessidade de correlação temporal entre as origens. C Na etapa de carga, a conveniência de descartar e recriar índices é determinada pela proporção entre dados novos e dados existentes, mas não pelo porte da tabela a ser indexada. D Dados estruturados e não estruturados são igualmente apropriados ao uso exclusivo em bancos relacionais, desde que indexados. E Dados não estruturados, embora não adotem esquema tabular clássico, tendem a apresentar maior aderência operacional a sistemas OLTP tradicionais em cenários transacionais de alta recorrência.$q$,$q$Assinale a opção correta no que se refere a dados estruturados e não estruturados, bem como a coleta, tratamento, armazenamento, integração e recuperação de dados. A Dados não estruturados são mais bem gerenciados quando armazenados em bancos não relacionais ou data lakes, por não seguirem modelo predefinido. B Na consolidação de dados provenientes de múltiplas fontes, a coincidência das identificações das entidades afasta a necessidade de correlação temporal entre as origens. C Na etapa de carga, a conveniência de descartar e recriar índices é determinada pela proporção entre dados novos e dados existentes, mas não pelo porte da tabela a ser indexada. D Dados estruturados e não estruturados são igualmente apropriados ao uso exclusivo em bancos relacionais, desde que indexados. E Dados não estruturados, embora não adotem esquema tabular clássico, tendem a apresentar maior aderência operacional a sistemas OLTP tradicionais em cenários transacionais de alta recorrência.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,28,$q$Tecnologia da Informação$q$,$q$Considerando a aplicação da álgebra relacional e da modelagem dimensional ao uso de banco de dados relacionais, bem como os conceitos de integridade referencial e de visões, assinale a opção correta. A A modelagem dimensional busca priorizar a normalização máxima das estruturas analíticas, a fim de reduzir redundâncias. B As visões, embora simplifiquem a formulação de consultas, introduzem processamento adicional em tempo de execução devido à resolução de suas definições. C Em visões construídas sobre junções um-para-muitos, a inserção costuma produzir efeito apenas na relação referente. D Na álgebra relacional, o encadeamento de operadores é possível porque seus resultados também são relações. E A integridade referencial pressupõe correspondência entre os valores de chave estrangeira e os valores da chave primária da relação referida.$q$,$q$Considerando a aplicação da álgebra relacional e da modelagem dimensional ao uso de banco de dados relacionais, bem como os conceitos de integridade referencial e de visões, assinale a opção correta. A A modelagem dimensional busca priorizar a normalização máxima das estruturas analíticas, a fim de reduzir redundâncias. B As visões, embora simplifiquem a formulação de consultas, introduzem processamento adicional em tempo de execução devido à resolução de suas definições. C Em visões construídas sobre junções um-para-muitos, a inserção costuma produzir efeito apenas na relação referente. D Na álgebra relacional, o encadeamento de operadores é possível porque seus resultados também são relações. E A integridade referencial pressupõe correspondência entre os valores de chave estrangeira e os valores da chave primária da relação referida.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,29,$q$Tecnologia da Informação$q$,$q$A respeito de mineração de dados, assinale a opção correta. A Regras de associação são empregadas para prever valores contínuos a partir de variáveis explicativas, sendo, por isso, uma técnica típica de modelagem preditiva supervisionada. B Na mineração de dados, técnicas de pré-processamento, como limpeza, transformação e seleção de atributos, influenciam diretamente o desempenho de tarefas como classificação e clusterização. C Na mineração de dados, a clusterização depende necessariamente de classes previamente rotuladas, razão pela qual se insere exclusivamente no aprendizado supervisionado. D No modelo CRISP-DM, a etapa de modelagem antecede a preparação dos dados, pois a definição prévia do algoritmo elimina a necessidade de transformação ou limpeza. E Classificação e detecção de anomalias são tarefas equivalentes, pois ambas têm por finalidade atribuir rótulos previamente conhecidos aos registros.$q$,$q$A respeito de mineração de dados, assinale a opção correta. A Regras de associação são empregadas para prever valores contínuos a partir de variáveis explicativas, sendo, por isso, uma técnica típica de modelagem preditiva supervisionada. B Na mineração de dados, técnicas de pré-processamento, como limpeza, transformação e seleção de atributos, influenciam diretamente o desempenho de tarefas como classificação e clusterização. C Na mineração de dados, a clusterização depende necessariamente de classes previamente rotuladas, razão pela qual se insere exclusivamente no aprendizado supervisionado. D No modelo CRISP-DM, a etapa de modelagem antecede a preparação dos dados, pois a definição prévia do algoritmo elimina a necessidade de transformação ou limpeza. E Classificação e detecção de anomalias são tarefas equivalentes, pois ambas têm por finalidade atribuir rótulos previamente conhecidos aos registros.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,30,$q$Tecnologia da Informação$q$,$q$Assinale a opção correta no que se refere a visualização e análise exploratória de dados por meio do Power BI e do Tableau. A No Power BI e no Tableau, os mecanismos de realce visual e de filtragem produzem, em regra, o mesmo efeito analítico, pois ambos removem dos visuais os dados não relacionados à seleção do usuário. B No Power BI, o drillthrough permite navegar de uma visão resumida para uma página detalhada já filtrada pelo contexto selecionado. C No Tableau, ações de dashboard restringem-se à navegação entre páginas, não podendo ser usadas para filtrar ou destacar marcas em outras visões do mesmo painel. D No Power BI, a interação entre visuais de uma mesma página depende da criação manual de ações equivalentes às do Tableau, inexistindo comportamento padrão de cross-filter ou cross-highlight. E No Power BI, recursos de exploração interativa substituem a necessidade de modelagem dos dados, pois filtros, destaques e ações passam a desempenhar função equivalente à estrutura analítica subjacente.$q$,$q$Assinale a opção correta no que se refere a visualização e análise exploratória de dados por meio do Power BI e do Tableau. A No Power BI e no Tableau, os mecanismos de realce visual e de filtragem produzem, em regra, o mesmo efeito analítico, pois ambos removem dos visuais os dados não relacionados à seleção do usuário. B No Power BI, o drillthrough permite navegar de uma visão resumida para uma página detalhada já filtrada pelo contexto selecionado. C No Tableau, ações de dashboard restringem-se à navegação entre páginas, não podendo ser usadas para filtrar ou destacar marcas em outras visões do mesmo painel. D No Power BI, a interação entre visuais de uma mesma página depende da criação manual de ações equivalentes às do Tableau, inexistindo comportamento padrão de cross-filter ou cross-highlight. E No Power BI, recursos de exploração interativa substituem a necessidade de modelagem dos dados, pois filtros, destaques e ações passam a desempenhar função equivalente à estrutura analítica subjacente.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Gerais, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido no CDN oficial da CEBRASPE (ausente na pasta do Google Drive do usuário). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,31,$q$Orçamento Público$q$,$q$Ao elaborar sua proposta orçamentária, o governo do município X previu simultaneamente a ampliação de investimentos em saneamento básico em áreas de maior vulnerabilidade social; a expansão de programa de transferência de renda; e o aumento temporário de despesas de manutenção urbana para preservar emprego e renda em momento de desaceleração econômica local. Com base nessa situação hipotética, assinale a opção em que são apresentadas as funções de intervenção na economia evidenciadas, respectivamente, na referida proposta orçamentária. A contábil, alocativa e regulatória B alocativa, distributiva e estabilizadora C estabilizadora, alocativa e patrimonial D normativa, fiscalizatória e arrecadatória E distributiva, estabilizadora e contábil$q$,$q$Ao elaborar sua proposta orçamentária, o governo do município X previu simultaneamente a ampliação de investimentos em saneamento básico em áreas de maior vulnerabilidade social; a expansão de programa de transferência de renda; e o aumento temporário de despesas de manutenção urbana para preservar emprego e renda em momento de desaceleração econômica local. Com base nessa situação hipotética, assinale a opção em que são apresentadas as funções de intervenção na economia evidenciadas, respectivamente, na referida proposta orçamentária. A contábil, alocativa e regulatória B alocativa, distributiva e estabilizadora C estabilizadora, alocativa e patrimonial D normativa, fiscalizatória e arrecadatória E distributiva, estabilizadora e contábil$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,32,$q$Orçamento Público$q$,$q$Orçamento-programa é definido como a técnica que A incorpora informações de desempenho à peça orçamentária, mas sem organizar necessariamente as despesas em torno de projetos articulados ao planejamento governamental. B estrutura a proposta orçamentária a partir da reprodução da despesa autorizada no exercício anterior, com acréscimos ou reduções marginais, preservando a base histórica de gastos como critério principal de decisão. C exige a reavaliação integral das despesas a cada novo ciclo orçamentário, sem tomar como ponto de partida obrigatório os programas e dotações anteriormente autorizados. D foca predominantemente o objeto do gasto e a classificação dos meios administrativos necessários ao funcionamento dos órgãos, privilegiando o controle formal dos insumos. E organiza a despesa segundo programas, objetivos, ações, produtos e metas, permitindo vincular a alocação de recursos ao planejamento governamental e à avaliação da atuação estatal.$q$,$q$Orçamento-programa é definido como a técnica que A incorpora informações de desempenho à peça orçamentária, mas sem organizar necessariamente as despesas em torno de projetos articulados ao planejamento governamental. B estrutura a proposta orçamentária a partir da reprodução da despesa autorizada no exercício anterior, com acréscimos ou reduções marginais, preservando a base histórica de gastos como critério principal de decisão. C exige a reavaliação integral das despesas a cada novo ciclo orçamentário, sem tomar como ponto de partida obrigatório os programas e dotações anteriormente autorizados. D foca predominantemente o objeto do gasto e a classificação dos meios administrativos necessários ao funcionamento dos órgãos, privilegiando o controle formal dos insumos. E organiza a despesa segundo programas, objetivos, ações, produtos e metas, permitindo vincular a alocação de recursos ao planejamento governamental e à avaliação da atuação estatal.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,33,$q$Orçamento Público$q$,$q$Considere que um governo pretenda iniciar investimento público que não está previsto no plano plurianual (PPA) e cuja execução orçamentária ultrapassará o exercício financeiro. Nesse caso, tal investimento, de acordo com a organização constitucional do orçamento público no Brasil, poderá iniciar-se A desde que conste na lei de diretrizes orçamentárias (LDO), já que o PPA não se relaciona com despesas de capital. B desde que previsto na lei orçamentária anual (LOA), a qual prevalece sobre os demais instrumentos de planejamento de médio prazo. C apenas após aprovação de lei que autorize a sua inclusão no PPA. D desde que haja saldo financeiro suficiente em conta bancária do ente público. E por ato administrativo, independentemente de previsão em instrumento de planejamento.$q$,$q$Considere que um governo pretenda iniciar investimento público que não está previsto no plano plurianual (PPA) e cuja execução orçamentária ultrapassará o exercício financeiro. Nesse caso, tal investimento, de acordo com a organização constitucional do orçamento público no Brasil, poderá iniciar-se A desde que conste na lei de diretrizes orçamentárias (LDO), já que o PPA não se relaciona com despesas de capital. B desde que previsto na lei orçamentária anual (LOA), a qual prevalece sobre os demais instrumentos de planejamento de médio prazo. C apenas após aprovação de lei que autorize a sua inclusão no PPA. D desde que haja saldo financeiro suficiente em conta bancária do ente público. E por ato administrativo, independentemente de previsão em instrumento de planejamento.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,34,$q$Orçamento Público$q$,$q$No que se refere à programação e à execução orçamentária e financeira, assinale a opção correta. A Alterações orçamentárias podem ser realizadas por transposição, remanejamento ou transferência de recursos sem autorização legislativa. B Créditos suplementares são destinados a despesas para as quais não haja dotação orçamentária específica. C Créditos extraordinários destinam-se ao reforço de qualquer dotação orçamentária já existente. D A abertura de créditos suplementares e especiais prescinde da indicação de recursos disponíveis e de autorização legislativa. E Créditos adicionais são autorizações de despesas não computadas ou insuficientemente dotadas na lei orçamentária.$q$,$q$No que se refere à programação e à execução orçamentária e financeira, assinale a opção correta. A Alterações orçamentárias podem ser realizadas por transposição, remanejamento ou transferência de recursos sem autorização legislativa. B Créditos suplementares são destinados a despesas para as quais não haja dotação orçamentária específica. C Créditos extraordinários destinam-se ao reforço de qualquer dotação orçamentária já existente. D A abertura de créditos suplementares e especiais prescinde da indicação de recursos disponíveis e de autorização legislativa. E Créditos adicionais são autorizações de despesas não computadas ou insuficientemente dotadas na lei orçamentária.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,35,$q$Orçamento Público$q$,$q$No que se refere à receita pública, assinale a opção correta. A As receitas correntes abrangem receitas tributárias recebidas de outras pessoas jurídicas de direito público, sendo vedada sua formação por operações de crédito. B A classificação da receita pública por categoria econômica identifica a destinação vinculada ou ordinária dos recursos, substituindo a classificação por fonte ou destinação de recursos. C As receitas patrimoniais são receitas extraorçamentárias, pois decorrem da exploração do patrimônio público e não integram a lei orçamentária. D A receita tributária é classificada como receita de capital, pois decorre de obrigação legal e tem caráter compulsório. E As receitas de capital abrangem operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital.$q$,$q$No que se refere à receita pública, assinale a opção correta. A As receitas correntes abrangem receitas tributárias recebidas de outras pessoas jurídicas de direito público, sendo vedada sua formação por operações de crédito. B A classificação da receita pública por categoria econômica identifica a destinação vinculada ou ordinária dos recursos, substituindo a classificação por fonte ou destinação de recursos. C As receitas patrimoniais são receitas extraorçamentárias, pois decorrem da exploração do patrimônio público e não integram a lei orçamentária. D A receita tributária é classificada como receita de capital, pois decorre de obrigação legal e tem caráter compulsório. E As receitas de capital abrangem operações de crédito, alienação de bens, amortização de empréstimos e transferências de capital.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,36,$q$Orçamento Público$q$,$q$No encerramento do exercício financeiro de determinado órgão público, foram identificadas as seguintes despesas: (i) contrato de serviços continuados empenhado globalmente, com parcela já prestada, liquidada e não paga; (ii) parcela do mesmo contrato empenhada, mas ainda sem comprovação da prestação do serviço; (iii) obrigação referente a exercício encerrado, para a qual havia crédito próprio e saldo suficiente no orçamento de origem, mas que não foi processada na época adequada; (iv) despesa sem empenho prévio, reconhecida apenas por declaração verbal do gestor. Considerando os estágios da despesa, os restos a pagar e as despesas de exercícios anteriores, assinale a opção correta. A A despesa descrita em (i) caracteriza restos a pagar processados; a descrita em (ii), restos a pagar não processados, preenchidas as condições normativas; a descrita em (iii) deve ser tratada como despesa de exercício anterior; e a descrita em (iv) é irregular, não bastando seu reconhecimento pela mera declaração verbal do gestor. B Todas as despesas especificadas podem ser inscritas em restos a pagar, desde que haja disponibilidade financeira suficiente ao final do exercício. C A despesa descrita em (i) corresponde a restos a pagar não processados; a descrita em (ii), a restos a pagar processados; a descrita em (iii) deve ser cancelada, pois não se admite pagamento de obrigação de exercício encerrado; e a descrita em (iv) não pode ser regularizada. D Somente a despesa descrita em (iii) admite inscrição como restos a pagar processados, já que havia crédito próprio e saldo suficiente no orçamento de origem, ainda que a despesa não tenha sido empenhada. E A liquidação pode ser presumida nas despesas descritas em (i) e (ii), pois o empenho global transfere ao credor direito líquido e certo ao pagamento integral do contrato; e as despesas descritas em (iii) e (iv) devem ser inscritas em restos a pagar não processados.$q$,$q$No encerramento do exercício financeiro de determinado órgão público, foram identificadas as seguintes despesas: (i) contrato de serviços continuados empenhado globalmente, com parcela já prestada, liquidada e não paga; (ii) parcela do mesmo contrato empenhada, mas ainda sem comprovação da prestação do serviço; (iii) obrigação referente a exercício encerrado, para a qual havia crédito próprio e saldo suficiente no orçamento de origem, mas que não foi processada na época adequada; (iv) despesa sem empenho prévio, reconhecida apenas por declaração verbal do gestor. Considerando os estágios da despesa, os restos a pagar e as despesas de exercícios anteriores, assinale a opção correta. A A despesa descrita em (i) caracteriza restos a pagar processados; a descrita em (ii), restos a pagar não processados, preenchidas as condições normativas; a descrita em (iii) deve ser tratada como despesa de exercício anterior; e a descrita em (iv) é irregular, não bastando seu reconhecimento pela mera declaração verbal do gestor. B Todas as despesas especificadas podem ser inscritas em restos a pagar, desde que haja disponibilidade financeira suficiente ao final do exercício. C A despesa descrita em (i) corresponde a restos a pagar não processados; a descrita em (ii), a restos a pagar processados; a descrita em (iii) deve ser cancelada, pois não se admite pagamento de obrigação de exercício encerrado; e a descrita em (iv) não pode ser regularizada. D Somente a despesa descrita em (iii) admite inscrição como restos a pagar processados, já que havia crédito próprio e saldo suficiente no orçamento de origem, ainda que a despesa não tenha sido empenhada. E A liquidação pode ser presumida nas despesas descritas em (i) e (ii), pois o empenho global transfere ao credor direito líquido e certo ao pagamento integral do contrato; e as despesas descritas em (iii) e (iv) devem ser inscritas em restos a pagar não processados.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,37,$q$Orçamento Público$q$,$q$O chefe do Poder Executivo de certo município pretende instituir, por ato normativo, programa permanente de transferência mensal de renda, com execução prevista por prazo indeterminado e impacto financeiro relevante. O processo administrativo contém apenas a justificativa social da medida, sem estimativa do impacto orçamentário-financeiro, sem declaração do ordenador a respeito da adequação com a LOA e compatibilidade com o PPA e a LDO, sem demonstração da origem dos recursos e sem comprovação de que a despesa não afetará as metas fiscais. Considerando a situação hipotética precedente, assinale a opção correta com base na Lei de Responsabilidade Fiscal (LRF). A A compensação exigida para despesa obrigatória continuada pode decorrer de operação de crédito, alienação de bens, superávit financeiro ou inscrição de restos a pagar não processados. B A despesa poderá ser executada se houver relevante finalidade social, pois programas redistributivos permanentes dispensam estimativa de impacto e declaração formal de adequação orçamentária. C A instituição do programa é irregular, pois o processo administrativo deveria conter a estimativa de impacto, a declaração de adequação e compatibilidade, e a origem dos recursos e compensação fiscal no caso de despesa continuada. D A despesa poderá ser empenhada e licitada antes da instrução fiscal exigida, desde que a estimativa de impacto e a compensação sejam apresentadas até o encerramento do exercício. E A despesa obrigatória de caráter continuado somente se configura quando criada por lei formal, não alcançando programas instituídos por medida provisória ou ato administrativo normativo.$q$,$q$O chefe do Poder Executivo de certo município pretende instituir, por ato normativo, programa permanente de transferência mensal de renda, com execução prevista por prazo indeterminado e impacto financeiro relevante. O processo administrativo contém apenas a justificativa social da medida, sem estimativa do impacto orçamentário-financeiro, sem declaração do ordenador a respeito da adequação com a LOA e compatibilidade com o PPA e a LDO, sem demonstração da origem dos recursos e sem comprovação de que a despesa não afetará as metas fiscais. Considerando a situação hipotética precedente, assinale a opção correta com base na Lei de Responsabilidade Fiscal (LRF). A A compensação exigida para despesa obrigatória continuada pode decorrer de operação de crédito, alienação de bens, superávit financeiro ou inscrição de restos a pagar não processados. B A despesa poderá ser executada se houver relevante finalidade social, pois programas redistributivos permanentes dispensam estimativa de impacto e declaração formal de adequação orçamentária. C A instituição do programa é irregular, pois o processo administrativo deveria conter a estimativa de impacto, a declaração de adequação e compatibilidade, e a origem dos recursos e compensação fiscal no caso de despesa continuada. D A despesa poderá ser empenhada e licitada antes da instrução fiscal exigida, desde que a estimativa de impacto e a compensação sejam apresentadas até o encerramento do exercício. E A despesa obrigatória de caráter continuado somente se configura quando criada por lei formal, não alcançando programas instituídos por medida provisória ou ato administrativo normativo.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,38,$q$Orçamento Público$q$,$q$Ao examinar a celebração, por determinado órgão, de termo de execução descentralizada, a auditoria verificou que havia motivação para execução por outro órgão, plano de trabalho previamente aprovado, indicação da classificação funcional programática, declaração de compatibilidade de custos e declaração de capacidade técnica. No entanto, a unidade descentralizada pretendia alterar o objeto posteriormente por apostila. Nessa situação hipotética, a celebração do referido termo de execução descentralizada A é regular apenas se tiver havido chamamento público obrigatório, pois a escolha da unidade descentralizada exige disputa entre órgãos e entidades federais. B atende às condições essenciais indicadas, sendo, entretanto, vedada a alteração do objeto aprovado, ainda que as demais mudanças no plano de trabalho sejam pretendidas por apostila. C é inválida, pois o referido termo exige transferência financeira prévia e análise jurídica obrigatória, independentemente do modelo utilizado. D é regular, e o objeto poderá ser alterado por apostila, desde que não haja aumento do valor global nem prorrogação da vigência originalmente pactuada. E é irregular, pois declaração de capacidade técnica e compatibilidade de custos são exigidas apenas para convênios e contratos de repasse.$q$,$q$Ao examinar a celebração, por determinado órgão, de termo de execução descentralizada, a auditoria verificou que havia motivação para execução por outro órgão, plano de trabalho previamente aprovado, indicação da classificação funcional programática, declaração de compatibilidade de custos e declaração de capacidade técnica. No entanto, a unidade descentralizada pretendia alterar o objeto posteriormente por apostila. Nessa situação hipotética, a celebração do referido termo de execução descentralizada A é regular apenas se tiver havido chamamento público obrigatório, pois a escolha da unidade descentralizada exige disputa entre órgãos e entidades federais. B atende às condições essenciais indicadas, sendo, entretanto, vedada a alteração do objeto aprovado, ainda que as demais mudanças no plano de trabalho sejam pretendidas por apostila. C é inválida, pois o referido termo exige transferência financeira prévia e análise jurídica obrigatória, independentemente do modelo utilizado. D é regular, e o objeto poderá ser alterado por apostila, desde que não haja aumento do valor global nem prorrogação da vigência originalmente pactuada. E é irregular, pois declaração de capacidade técnica e compatibilidade de custos são exigidas apenas para convênios e contratos de repasse.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,39,$q$Orçamento Público$q$,$q$O decreto de programação orçamentária e financeira (DPOF) A disciplina somente o pagamento de restos a pagar, sem interferir nos limites de movimentação e empenho das despesas do orçamento corrente. B configura crédito adicional aberto pelo Poder Executivo para ampliar dotações insuficientes da LOA e autorizar despesas não previstas no orçamento anual. C substitui a LOA na fase de execução, pois fixa novas dotações, altera categorias de programação e redefine prioridades sem depender do disposto nessa lei. D é instrumento facultativo de gestão de caixa, editado apenas quando houver frustração de receita ou necessidade de contingenciamento de despesas. E operacionaliza a programação financeira e o cronograma mensal de desembolso, compatibilizando empenho, pagamento, arrecadação e metas fiscais após a publicação da LOA.$q$,$q$O decreto de programação orçamentária e financeira (DPOF) A disciplina somente o pagamento de restos a pagar, sem interferir nos limites de movimentação e empenho das despesas do orçamento corrente. B configura crédito adicional aberto pelo Poder Executivo para ampliar dotações insuficientes da LOA e autorizar despesas não previstas no orçamento anual. C substitui a LOA na fase de execução, pois fixa novas dotações, altera categorias de programação e redefine prioridades sem depender do disposto nessa lei. D é instrumento facultativo de gestão de caixa, editado apenas quando houver frustração de receita ou necessidade de contingenciamento de despesas. E operacionaliza a programação financeira e o cronograma mensal de desembolso, compatibilizando empenho, pagamento, arrecadação e metas fiscais após a publicação da LOA.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,40,$q$Políticas Públicas$q$,$q$O conceito de política pública A pode ser entendido como qualquer intenção formalizada por um agente público, mesmo que sem efeitos concretos. B refere-se à aplicação de teorias unidisciplinares, geralmente restritas à ciência política, devido à influência do sistema partidário nas decisões de governo. C atém-se a respostas técnico-racionais a um problema ou uma questão de interesse formuladas por servidores ocupantes de cargo público de provimento efetivo. D pode ser sintetizado como aquilo que o governo escolhe fazer ou não fazer. E circunscreve-se a medidas normativas pontuais destinadas à resolução de entraves burocráticos.$q$,$q$O conceito de política pública A pode ser entendido como qualquer intenção formalizada por um agente público, mesmo que sem efeitos concretos. B refere-se à aplicação de teorias unidisciplinares, geralmente restritas à ciência política, devido à influência do sistema partidário nas decisões de governo. C atém-se a respostas técnico-racionais a um problema ou uma questão de interesse formuladas por servidores ocupantes de cargo público de provimento efetivo. D pode ser sintetizado como aquilo que o governo escolhe fazer ou não fazer. E circunscreve-se a medidas normativas pontuais destinadas à resolução de entraves burocráticos.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,41,$q$Políticas Públicas$q$,$q$Entre unidades políticas primárias em contextos de políticas redistributivas, estabelece-se uma estrutura de poder A de elite conflitual. B multicêntrica. C baseada na teoria do equilíbrio. D de troca de favores. E pluralística.$q$,$q$Entre unidades políticas primárias em contextos de políticas redistributivas, estabelece-se uma estrutura de poder A de elite conflitual. B multicêntrica. C baseada na teoria do equilíbrio. D de troca de favores. E pluralística.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,42,$q$Políticas Públicas$q$,$q$A abordagem conceitual policêntrica de políticas públicas A deriva da tradição histórica intervencionista do Estado brasileiro desde a época da República Velha. B reconhece a superioridade objetiva do Estado em relação a temas normativos e burocráticos. C considera as redes de políticas públicas como parte dos protagonistas na formulação de políticas públicas. D destaca que toda política pública necessariamente emana de um ator estatal. E ressalta a superioridade hierárquica do Estado para identificar e corrigir falhas de mercado existentes.$q$,$q$A abordagem conceitual policêntrica de políticas públicas A deriva da tradição histórica intervencionista do Estado brasileiro desde a época da República Velha. B reconhece a superioridade objetiva do Estado em relação a temas normativos e burocráticos. C considera as redes de políticas públicas como parte dos protagonistas na formulação de políticas públicas. D destaca que toda política pública necessariamente emana de um ator estatal. E ressalta a superioridade hierárquica do Estado para identificar e corrigir falhas de mercado existentes.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,43,$q$Políticas Públicas$q$,$q$O processo de definição da agenda de políticas públicas envolve tanto atores visíveis quanto atores relativamente ocultos. Assinale a opção que apresenta atores relativamente ocultos que participam desse processo. A principais partidos políticos B burocratas de carreira C personalidades influentes da mídia D parlamentares proeminentes E ministros de Estado$q$,$q$O processo de definição da agenda de políticas públicas envolve tanto atores visíveis quanto atores relativamente ocultos. Assinale a opção que apresenta atores relativamente ocultos que participam desse processo. A principais partidos políticos B burocratas de carreira C personalidades influentes da mídia D parlamentares proeminentes E ministros de Estado$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,44,$q$Políticas Públicas$q$,$q$A nodalidade, enquanto instrumento utilizado no processo de formulação de políticas públicas, está relacionada A à execução de ações em áreas como saúde e educação. B a instâncias de regulação e comitês consultivos de viés normativo. C ao acesso a informações governamentais relevantes. D à arrecadação e transferência de recursos financeiros. E a estruturas organizacionais e burocráticas.$q$,$q$A nodalidade, enquanto instrumento utilizado no processo de formulação de políticas públicas, está relacionada A à execução de ações em áreas como saúde e educação. B a instâncias de regulação e comitês consultivos de viés normativo. C ao acesso a informações governamentais relevantes. D à arrecadação e transferência de recursos financeiros. E a estruturas organizacionais e burocráticas.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,45,$q$Políticas Públicas$q$,$q$No ciclo das políticas públicas, o momento de execução da política pública, quando os planos estabelecidos se concretizam, corresponde à fase denominada A avaliação. B formação da agenda. C implementação. D tomada de decisão. E formulação.$q$,$q$No ciclo das políticas públicas, o momento de execução da política pública, quando os planos estabelecidos se concretizam, corresponde à fase denominada A avaliação. B formação da agenda. C implementação. D tomada de decisão. E formulação.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,46,$q$Políticas Públicas$q$,$q$Os indicadores que medem o desempenho das atividades vinculadas à execução ou à forma como o trabalho é realizado para produzir os bens e serviços são indicadores de A processo. B resultado final. C resultado parcial. D insumo. E produto.$q$,$q$Os indicadores que medem o desempenho das atividades vinculadas à execução ou à forma como o trabalho é realizado para produzir os bens e serviços são indicadores de A processo. B resultado final. C resultado parcial. D insumo. E produto.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,47,$q$Políticas Públicas$q$,$q$No contexto das políticas públicas, a avaliação formativa é utilizada principalmente para A subsidiar a tomada de decisão quanto à adoção ou à expansão de políticas públicas. B apoiar a implementação ou o aperfeiçoamento de políticas públicas. C analisar a teoria do programa, considerando-se sua consistência e lógica interna. D avaliar de que forma a liderança e a estratégia influenciam os resultados das políticas públicas. E comparar diferentes políticas públicas para identificar aquelas cujo retorno justifique sua execução.$q$,$q$No contexto das políticas públicas, a avaliação formativa é utilizada principalmente para A subsidiar a tomada de decisão quanto à adoção ou à expansão de políticas públicas. B apoiar a implementação ou o aperfeiçoamento de políticas públicas. C analisar a teoria do programa, considerando-se sua consistência e lógica interna. D avaliar de que forma a liderança e a estratégia influenciam os resultados das políticas públicas. E comparar diferentes políticas públicas para identificar aquelas cujo retorno justifique sua execução.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,48,$q$Finanças Públicas$q$,$q$Observa-se a aplicação da função distributiva do Estado quando, por exemplo, A o Estado transfere recursos oriundos da tributação dos indivíduos de renda mais alta para o financiamento de programas sociais de moradias populares. B o Estado, diante de uma crise que interrompe abruptamente a renda de trabalhadores informais e autônomos, institui um benefício temporário de transferência direta de renda. C o Estado, na situação em que a economia opera acima do seu potencial e surgem pressões inflacionárias, age em sentido contracionista, limitando o crescimento real do gasto público por meio de regras fiscais institucionalizadas. D o Estado atende a reclamações sobre a falta de iluminação pública em determinada região, fornecendo o serviço. E o Estado, depois de acionado, fornece medicamento para o tratamento de doença grave de paciente cadastrado no SUS.$q$,$q$Observa-se a aplicação da função distributiva do Estado quando, por exemplo, A o Estado transfere recursos oriundos da tributação dos indivíduos de renda mais alta para o financiamento de programas sociais de moradias populares. B o Estado, diante de uma crise que interrompe abruptamente a renda de trabalhadores informais e autônomos, institui um benefício temporário de transferência direta de renda. C o Estado, na situação em que a economia opera acima do seu potencial e surgem pressões inflacionárias, age em sentido contracionista, limitando o crescimento real do gasto público por meio de regras fiscais institucionalizadas. D o Estado atende a reclamações sobre a falta de iluminação pública em determinada região, fornecendo o serviço. E o Estado, depois de acionado, fornece medicamento para o tratamento de doença grave de paciente cadastrado no SUS.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,49,$q$Finanças Públicas$q$,$q$No desempenho de suas funções, o setor público tem como principal fonte de receita a arrecadação tributária. A curva de Laffer expressa a relação entre a alíquota tributária e a receita arrecadada pelo governo. Considerando-se essa relação e tendo em vista os conceitos de progressividade, regressividade e neutralidade, é correto afirmar que, a partir de determinado ponto, A o aumento da alíquota reduz a despesa pública relativa, porque a arrecadação será superior à despesa pública. B a diminuição da alíquota aumenta a arrecadação, porque produz evasão e(ou) desestímulos às atividades formais. C o aumento da alíquota aumenta a arrecadação, porque produz estímulos às atividades formais. D o aumento da alíquota aumenta a despesa pública, porque produz estímulos ao aumento do gasto público. E o aumento da alíquota reduz a arrecadação, porque produz evasão e(ou) desestímulos às atividades formais.$q$,$q$No desempenho de suas funções, o setor público tem como principal fonte de receita a arrecadação tributária. A curva de Laffer expressa a relação entre a alíquota tributária e a receita arrecadada pelo governo. Considerando-se essa relação e tendo em vista os conceitos de progressividade, regressividade e neutralidade, é correto afirmar que, a partir de determinado ponto, A o aumento da alíquota reduz a despesa pública relativa, porque a arrecadação será superior à despesa pública. B a diminuição da alíquota aumenta a arrecadação, porque produz evasão e(ou) desestímulos às atividades formais. C o aumento da alíquota aumenta a arrecadação, porque produz estímulos às atividades formais. D o aumento da alíquota aumenta a despesa pública, porque produz estímulos ao aumento do gasto público. E o aumento da alíquota reduz a arrecadação, porque produz evasão e(ou) desestímulos às atividades formais.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,50,$q$Finanças Públicas$q$,$q$Pelo conceito da equidade na tributação, cada contribuinte deve contribuir com uma parcela justa para cobrir os custos do setor público. Nesse contexto, o princípio da capacidade de pagamento A preconiza que o sistema tributário não provoque uma distorção da alocação de recursos, sob pena de prejudicar a eficiência do sistema. B estabelece que o ônus tributário deve ser tal que se garanta a equidade, considerada a capacidade econômica do contribuinte. C está relacionado com a facilidade de operacionalização da cobrança de tributo. D estabelece que cada indivíduo deveria contribuir com uma quantia proporcional aos benefícios gerados pelo consumo do bem público. E é associado ao financiamento de serviços públicos de acordo com a quantidade exata de serviços consumidos pelo cidadão.$q$,$q$Pelo conceito da equidade na tributação, cada contribuinte deve contribuir com uma parcela justa para cobrir os custos do setor público. Nesse contexto, o princípio da capacidade de pagamento A preconiza que o sistema tributário não provoque uma distorção da alocação de recursos, sob pena de prejudicar a eficiência do sistema. B estabelece que o ônus tributário deve ser tal que se garanta a equidade, considerada a capacidade econômica do contribuinte. C está relacionado com a facilidade de operacionalização da cobrança de tributo. D estabelece que cada indivíduo deveria contribuir com uma quantia proporcional aos benefícios gerados pelo consumo do bem público. E é associado ao financiamento de serviços públicos de acordo com a quantidade exata de serviços consumidos pelo cidadão.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,51,$q$Finanças Públicas$q$,$q$Assinale a opção correta acerca das transferências voluntárias. A O ente transferidor deve possuir dotação orçamentária própria para a realização do repasse. B O beneficiário deve demonstrar que aplica os percentuais máximos de recursos exigidos pela Constituição Federal de 1988 nas áreas da saúde e da educação. C Os recursos recebidos por transferência voluntária podem ser utilizados para objetivos e finalidades diversos dos pactuados, desde que haja aprovação do Poder Legislativo do ente beneficiário. D A transferência deve respeitar as vedações e limitações previstas na Constituição Federal de 1988, exceto aquelas relacionadas à realização de operações de crédito entre entes federativos. E O ente beneficiário deve comprovar que está inadimplente em relação aos tributos, empréstimos e financiamentos devidos ao ente que realizará a transferência, bem como demonstrar que prestou contas adequadamente de eventuais recursos anteriormente recebidos.$q$,$q$Assinale a opção correta acerca das transferências voluntárias. A O ente transferidor deve possuir dotação orçamentária própria para a realização do repasse. B O beneficiário deve demonstrar que aplica os percentuais máximos de recursos exigidos pela Constituição Federal de 1988 nas áreas da saúde e da educação. C Os recursos recebidos por transferência voluntária podem ser utilizados para objetivos e finalidades diversos dos pactuados, desde que haja aprovação do Poder Legislativo do ente beneficiário. D A transferência deve respeitar as vedações e limitações previstas na Constituição Federal de 1988, exceto aquelas relacionadas à realização de operações de crédito entre entes federativos. E O ente beneficiário deve comprovar que está inadimplente em relação aos tributos, empréstimos e financiamentos devidos ao ente que realizará a transferência, bem como demonstrar que prestou contas adequadamente de eventuais recursos anteriormente recebidos.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,52,$q$Finanças Públicas$q$,$q$Ao final de cada bimestre, caso se constate que a arrecadação das receitas poderá ser insuficiente para o cumprimento das metas de resultado primário ou nominal previstas no anexo de metas fiscais, os Poderes e o Ministério Público deverão adotar medidas de ajuste fiscal. A adoção dessas providências deve ocorrer A imediatamente após a verificação da insuficiência de receitas. B ao final do exercício financeiro em que constatada a insuficiência de receitas. C conforme conveniência e oportunidade da administração pública. D até trinta dias após a verificação da insuficiência de receitas. E até sessenta dias após a verificação da insuficiência de receitas.$q$,$q$Ao final de cada bimestre, caso se constate que a arrecadação das receitas poderá ser insuficiente para o cumprimento das metas de resultado primário ou nominal previstas no anexo de metas fiscais, os Poderes e o Ministério Público deverão adotar medidas de ajuste fiscal. A adoção dessas providências deve ocorrer A imediatamente após a verificação da insuficiência de receitas. B ao final do exercício financeiro em que constatada a insuficiência de receitas. C conforme conveniência e oportunidade da administração pública. D até trinta dias após a verificação da insuficiência de receitas. E até sessenta dias após a verificação da insuficiência de receitas.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,53,$q$Finanças Públicas$q$,$q$Em 2026, aconteceram os seguintes eventos em determinado estado da Federação: I contratação de empréstimo junto a banco de desenvolvimento regional, para fins de investimentos em infraestrutura pública, com prazo de pagamento em dez anos; II assinatura de contrato de garantia em favor de uma empresa estatal de saneamento, para assegurar o pagamento de um financiamento contratado junto a uma instituição financeira internacional; III reconhecimento formal de uma dívida referente a despesas realizadas em exercícios anteriores que não haviam sido registradas contabilmente. Nessa situação hipotética, houve operação de crédito A apenas no evento I. B apenas no evento II. C apenas nos eventos I e III. D apenas nos eventos II e III. E em todos os eventos enumerados.$q$,$q$Em 2026, aconteceram os seguintes eventos em determinado estado da Federação: I contratação de empréstimo junto a banco de desenvolvimento regional, para fins de investimentos em infraestrutura pública, com prazo de pagamento em dez anos; II assinatura de contrato de garantia em favor de uma empresa estatal de saneamento, para assegurar o pagamento de um financiamento contratado junto a uma instituição financeira internacional; III reconhecimento formal de uma dívida referente a despesas realizadas em exercícios anteriores que não haviam sido registradas contabilmente. Nessa situação hipotética, houve operação de crédito A apenas no evento I. B apenas no evento II. C apenas nos eventos I e III. D apenas nos eventos II e III. E em todos os eventos enumerados.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,54,$q$Finanças Públicas$q$,$q$Suponha que determinado município tenha estimado sua receita corrente líquida em R$ 106.000.000. Nesse caso, o limite de despesa de pessoal do Poder Executivo municipal será, em R$, de A 63.600.000. B 34.344.000. C 31.164.000. D 3.816.000. E 3.180.000.$q$,$q$Suponha que determinado município tenha estimado sua receita corrente líquida em R$ 106.000.000. Nesse caso, o limite de despesa de pessoal do Poder Executivo municipal será, em R$, de A 63.600.000. B 34.344.000. C 31.164.000. D 3.816.000. E 3.180.000.$q$,'X',1,'annulled',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active. Item anulado no gabarito oficial; não é exibido aos estudantes.$q$),
(2026,55,$q$Finanças Públicas$q$,$q$Um ente estadual, em processo de elaboração da LOA para 2027, analisou o seguinte histórico de projeção de receita. exercício valor (em milhões de R$): 2024: 8.000; 2025: 8.230; 2026: 9.000. Para a elaboração da proposta orçamentária de 2027, o Poder Executivo estadual estimou uma arrecadação de R$ 9.880 milhões, considerando fatores como o crescimento econômico esperado, a inflação projetada, o aprimoramento da fiscalização tributária e outros elementos relevantes. Em atendimento às exigências legais, também projetou a arrecadação para os dois exercícios subsequentes: R$ 10.000 milhões em 2028 e R$ 10.200 milhões em 2029. O Poder Executivo estadual encaminhou os estudos, as metodologias e as premissas de cálculo aos demais Poderes dez dias antes do prazo final para a apresentação das respectivas propostas orçamentárias. Durante a tramitação da proposta, a assembleia legislativa decidiu elevar a previsão de arrecadação em R$ 600 milhões, sem, contudo, apresentar estudos técnicos adicionais. Com base nas informações apresentadas, é correto afirmar que, nesse processo hipotético, A houve duas irregularidades: a reestimativa de receita pelo Poder Legislativo sem comprovação de erro ou omissão técnica e a projeção de receitas apenas para dois anos seguintes a 2027. B houve somente uma irregularidade: a reestimativa de receita pelo Poder Legislativo sem comprovação de erro ou omissão técnica. C houve duas irregularidades: a disponibilização intempestiva das estimativas de receita aos demais Poderes e a reestimativa de receita pelo Poder Legislativo sem comprovação de erro ou omissão técnica. D não houve nenhuma irregularidade: o trâmite descrito está em conformidade com as normas e leis de finanças públicas. E houve somente uma irregularidade: a disponibilização intempestiva das estimativas de receita aos demais Poderes.$q$,$q$Um ente estadual, em processo de elaboração da LOA para 2027, analisou o seguinte histórico de projeção de receita. exercício valor (em milhões de R$): 2024: 8.000; 2025: 8.230; 2026: 9.000. Para a elaboração da proposta orçamentária de 2027, o Poder Executivo estadual estimou uma arrecadação de R$ 9.880 milhões, considerando fatores como o crescimento econômico esperado, a inflação projetada, o aprimoramento da fiscalização tributária e outros elementos relevantes. Em atendimento às exigências legais, também projetou a arrecadação para os dois exercícios subsequentes: R$ 10.000 milhões em 2028 e R$ 10.200 milhões em 2029. O Poder Executivo estadual encaminhou os estudos, as metodologias e as premissas de cálculo aos demais Poderes dez dias antes do prazo final para a apresentação das respectivas propostas orçamentárias. Durante a tramitação da proposta, a assembleia legislativa decidiu elevar a previsão de arrecadação em R$ 600 milhões, sem, contudo, apresentar estudos técnicos adicionais. Com base nas informações apresentadas, é correto afirmar que, nesse processo hipotético, A houve duas irregularidades: a reestimativa de receita pelo Poder Legislativo sem comprovação de erro ou omissão técnica e a projeção de receitas apenas para dois anos seguintes a 2027. B houve somente uma irregularidade: a reestimativa de receita pelo Poder Legislativo sem comprovação de erro ou omissão técnica. C houve duas irregularidades: a disponibilização intempestiva das estimativas de receita aos demais Poderes e a reestimativa de receita pelo Poder Legislativo sem comprovação de erro ou omissão técnica. D não houve nenhuma irregularidade: o trâmite descrito está em conformidade com as normas e leis de finanças públicas. E houve somente uma irregularidade: a disponibilização intempestiva das estimativas de receita aos demais Poderes.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,56,$q$Auditoria Governamental$q$,$q$Caso um auditor do órgão de controle externo tome por base, em suas avaliações, o relatório elaborado por um auditor da controladoria geral do município, A o auditor interno deve assinar o relatório de auditoria juntamente com o auditor do órgão de controle externo. B o auditor externo deve obter evidência da competência e independência do auditor interno, bem como da qualidade do trabalho realizado. C o auditor externo deve presumir a competência do auditor interno para a realização de um trabalho de qualidade. D o órgão de controle externo não será responsável pelas conclusões de seu auditor, uma vez que foram baseadas no trabalho da auditoria interna. E o órgão de controle interno deverá ser consultado e assumir a responsabilidade pelas conclusões do auditor externo.$q$,$q$Caso um auditor do órgão de controle externo tome por base, em suas avaliações, o relatório elaborado por um auditor da controladoria geral do município, A o auditor interno deve assinar o relatório de auditoria juntamente com o auditor do órgão de controle externo. B o auditor externo deve obter evidência da competência e independência do auditor interno, bem como da qualidade do trabalho realizado. C o auditor externo deve presumir a competência do auditor interno para a realização de um trabalho de qualidade. D o órgão de controle externo não será responsável pelas conclusões de seu auditor, uma vez que foram baseadas no trabalho da auditoria interna. E o órgão de controle interno deverá ser consultado e assumir a responsabilidade pelas conclusões do auditor externo.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,57,$q$Auditoria Governamental$q$,$q$Na fase de execução de uma auditoria governamental cujo objetivo seja avaliar as demonstrações contábeis da dívida pública, cabe ao auditor verificar se as informações ou as condições reais do objeto auditado estão de acordo com A as normas que regulam o sistema financeiro. B o ambiente de controle. C o plano anual de auditoria interna. D os critérios aplicáveis. E o código de ética dos auditores.$q$,$q$Na fase de execução de uma auditoria governamental cujo objetivo seja avaliar as demonstrações contábeis da dívida pública, cabe ao auditor verificar se as informações ou as condições reais do objeto auditado estão de acordo com A as normas que regulam o sistema financeiro. B o ambiente de controle. C o plano anual de auditoria interna. D os critérios aplicáveis. E o código de ética dos auditores.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,58,$q$Auditoria Governamental$q$,$q$A auditoria financeira regulada pela norma ISSAI 200 visa, por meio da coleta de evidências, fornecer aos usuários uma asseguração A incondicional, sob a forma de gráfico de demonstrações contábeis. B absoluta, em ofício assinado por, pelo menos, dois auditores. C limitada, demonstrada em planilha detalhada. D razoável, na forma de uma opinião e(ou) relatório de auditoria. E exata, mediante parecer técnico justificado.$q$,$q$A auditoria financeira regulada pela norma ISSAI 200 visa, por meio da coleta de evidências, fornecer aos usuários uma asseguração A incondicional, sob a forma de gráfico de demonstrações contábeis. B absoluta, em ofício assinado por, pelo menos, dois auditores. C limitada, demonstrada em planilha detalhada. D razoável, na forma de uma opinião e(ou) relatório de auditoria. E exata, mediante parecer técnico justificado.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,59,$q$Auditoria Governamental$q$,$q$Na auditoria financeira, o conceito de materialidade deve ser aplicado A apenas em termos descritivos em todos os trabalhos. B apenas em termos qualitativos em todos os trabalhos. C em termos quantitativos e, quando pertinente, em termos qualitativos. D apenas em termos quantitativos em todos os trabalhos. E em termos qualitativos e, quando pertinente, em termos quantitativos.$q$,$q$Na auditoria financeira, o conceito de materialidade deve ser aplicado A apenas em termos descritivos em todos os trabalhos. B apenas em termos qualitativos em todos os trabalhos. C em termos quantitativos e, quando pertinente, em termos qualitativos. D apenas em termos quantitativos em todos os trabalhos. E em termos qualitativos e, quando pertinente, em termos quantitativos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,60,$q$Auditoria Governamental$q$,$q$Assinale a opção correta em relação ao método de amostragem utilizado na auditoria de conformidade no setor público. A Independentemente do método de amostragem utilizado, o auditor deve registrar que suas conclusões se aplicam a todo o universo da auditoria. B Em se tratando de amostragem não probabilística, o auditor deve registrar o grau de incerteza embutido na generalização das conclusões. C Em amostragem estatística, deve-se registrar no relatório o grau de incerteza embutido na generalização das conclusões. D Na amostragem probabilística, não há grau de incerteza a ser registrado. E Na amostragem estatística, o auditor deve registrar que as conclusões se limitam à amostra analisada.$q$,$q$Assinale a opção correta em relação ao método de amostragem utilizado na auditoria de conformidade no setor público. A Independentemente do método de amostragem utilizado, o auditor deve registrar que suas conclusões se aplicam a todo o universo da auditoria. B Em se tratando de amostragem não probabilística, o auditor deve registrar o grau de incerteza embutido na generalização das conclusões. C Em amostragem estatística, deve-se registrar no relatório o grau de incerteza embutido na generalização das conclusões. D Na amostragem probabilística, não há grau de incerteza a ser registrado. E Na amostragem estatística, o auditor deve registrar que as conclusões se limitam à amostra analisada.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,61,$q$Auditoria Governamental$q$,$q$De acordo com as normas de auditoria do TCU, no contexto de uma auditoria financeira do ativo imobilizado, os papéis de trabalho A registram minuciosamente as verificações realizadas na folha de pagamento. B complementam o relatório de auditoria, fornecendo informações sobre todas as áreas do órgão auditado. C viabilizam a execução diária dos processos de trabalho a cargo dos gestores públicos. D fornecem às partes interessadas uma descrição resumida da opinião do auditor. E evidenciam o trabalho desenvolvido pelo auditor, suas verificações e conclusões.$q$,$q$De acordo com as normas de auditoria do TCU, no contexto de uma auditoria financeira do ativo imobilizado, os papéis de trabalho A registram minuciosamente as verificações realizadas na folha de pagamento. B complementam o relatório de auditoria, fornecendo informações sobre todas as áreas do órgão auditado. C viabilizam a execução diária dos processos de trabalho a cargo dos gestores públicos. D fornecem às partes interessadas uma descrição resumida da opinião do auditor. E evidenciam o trabalho desenvolvido pelo auditor, suas verificações e conclusões.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,62,$q$Auditoria Governamental$q$,$q$Se, no processo de auditoria financeira do ativo imobilizado, forem identificados elevados riscos de distorções relevantes, o auditor, de acordo com a ISSAI 200, deve A obter evidência de auditoria limitada ao essencial. B aplicar procedimentos de auditoria resumidos e contundentes. C desconsiderar o risco de controle. D reavaliar o risco de distorções relevantes e aplicar procedimentos de auditoria sucintos e objetivos. E obter evidência de auditoria mais persuasiva.$q$,$q$Se, no processo de auditoria financeira do ativo imobilizado, forem identificados elevados riscos de distorções relevantes, o auditor, de acordo com a ISSAI 200, deve A obter evidência de auditoria limitada ao essencial. B aplicar procedimentos de auditoria resumidos e contundentes. C desconsiderar o risco de controle. D reavaliar o risco de distorções relevantes e aplicar procedimentos de auditoria sucintos e objetivos. E obter evidência de auditoria mais persuasiva.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,63,$q$Auditoria Governamental$q$,$q$Assinale a opção que indica o conceito a ser observado pelo auditor no exame dos documentos originais para determinar se a transação realizada é adequada em função da atividade da organização. A apropriação B autenticidade C aprovação D registro E normalidade$q$,$q$Assinale a opção que indica o conceito a ser observado pelo auditor no exame dos documentos originais para determinar se a transação realizada é adequada em função da atividade da organização. A apropriação B autenticidade C aprovação D registro E normalidade$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,64,$q$Auditoria Governamental$q$,$q$Caso não consiga obter evidência adequada e suficiente para caracterizar um achado, o auditor, ao elaborar o relatório de uma auditoria operacional, deve A relatar o achado, registrando qualquer evidência que conseguiu obter. B relatar o achado e abster-se de formular recomendações. C abster-se de relatar o achado. D registrar o achado no campo referente a limitações ao trabalho executado. E deixar claro para os destinatários que o achado tem eficácia limitada.$q$,$q$Caso não consiga obter evidência adequada e suficiente para caracterizar um achado, o auditor, ao elaborar o relatório de uma auditoria operacional, deve A relatar o achado, registrando qualquer evidência que conseguiu obter. B relatar o achado e abster-se de formular recomendações. C abster-se de relatar o achado. D registrar o achado no campo referente a limitações ao trabalho executado. E deixar claro para os destinatários que o achado tem eficácia limitada.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,65,$q$Planejamento e Controle Orçamentário$q$,$q$A respeito do planejamento governamental no contexto da administração pública brasileira, julgue os seguintes itens. I O planejamento governamental constitui função permanente do governo e, após a aprovação dos planos, estes podem adquirir natureza jurídica capaz de instituir direitos e obrigações e autorizar a realização de despesas. II Na administração pública, o planejamento caracteriza-se como atividade desenvolvida exclusivamente no nível estratégico da organização, cabendo aos níveis tático e operacional a execução das ações previamente definidas. III O planejamento apresenta-se como processo contínuo que fundamenta, antecede e acompanha a elaboração orçamentária. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$A respeito do planejamento governamental no contexto da administração pública brasileira, julgue os seguintes itens. I O planejamento governamental constitui função permanente do governo e, após a aprovação dos planos, estes podem adquirir natureza jurídica capaz de instituir direitos e obrigações e autorizar a realização de despesas. II Na administração pública, o planejamento caracteriza-se como atividade desenvolvida exclusivamente no nível estratégico da organização, cabendo aos níveis tático e operacional a execução das ações previamente definidas. III O planejamento apresenta-se como processo contínuo que fundamenta, antecede e acompanha a elaboração orçamentária. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,66,$q$Planejamento e Controle Orçamentário$q$,$q$Julgue os itens a seguir, relativos ao plano plurianual (PPA), à lei orçamentária anual (LOA) e à lei de diretrizes orçamentárias (LDO). I A LOA compreende exclusivamente o orçamento fiscal e o orçamento da seguridade social. II O PPA estabelece, de forma regionalizada, as diretrizes, os objetivos e as metas da administração pública para as despesas de capital e outras delas decorrentes, bem como para os programas de duração continuada. III A LDO orienta a elaboração da LOA e dispõe sobre alterações na legislação tributária. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$Julgue os itens a seguir, relativos ao plano plurianual (PPA), à lei orçamentária anual (LOA) e à lei de diretrizes orçamentárias (LDO). I A LOA compreende exclusivamente o orçamento fiscal e o orçamento da seguridade social. II O PPA estabelece, de forma regionalizada, as diretrizes, os objetivos e as metas da administração pública para as despesas de capital e outras delas decorrentes, bem como para os programas de duração continuada. III A LDO orienta a elaboração da LOA e dispõe sobre alterações na legislação tributária. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,67,$q$Planejamento e Controle Orçamentário$q$,$q$Considerando as disposições constitucionais relacionadas ao planejamento e ao orçamento públicos, julgue os itens que se seguem. I Nenhum investimento cuja execução ultrapasse um exercício financeiro poderá ser iniciado sem prévia inclusão no PPA ou sem lei que autorize sua inclusão. II A LOA pode conter autorização para contratação de operações de crédito, inclusive por antecipação de receita. III A LOA poderá conter dispositivos estranhos à previsão da receita e à fixação da despesa quando destinados à criação de programas governamentais permanentes. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$Considerando as disposições constitucionais relacionadas ao planejamento e ao orçamento públicos, julgue os itens que se seguem. I Nenhum investimento cuja execução ultrapasse um exercício financeiro poderá ser iniciado sem prévia inclusão no PPA ou sem lei que autorize sua inclusão. II A LOA pode conter autorização para contratação de operações de crédito, inclusive por antecipação de receita. III A LOA poderá conter dispositivos estranhos à previsão da receita e à fixação da despesa quando destinados à criação de programas governamentais permanentes. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,68,$q$Planejamento e Controle Orçamentário$q$,$q$Assinale a opção correta acerca dos mecanismos de retificação do orçamento. A As alterações de fonte de recursos e de modalidade de aplicação dependem necessariamente da abertura de créditos adicionais. B A descentralização de créditos orçamentários elimina a necessidade de transferência dos recursos financeiros correspondentes entre as unidades envolvidas. C A abertura de créditos suplementares exige autorização legislativa específica para cada alteração realizada durante a execução orçamentária. D A LOA pode conter autorização para abertura de créditos suplementares, permitindo determinadas retificações orçamentárias durante a execução do orçamento. E Os créditos extraordinários destinam-se às hipóteses de guerra, comoção interna ou calamidade pública, sendo vedada sua abertura por outra situação de urgência.$q$,$q$Assinale a opção correta acerca dos mecanismos de retificação do orçamento. A As alterações de fonte de recursos e de modalidade de aplicação dependem necessariamente da abertura de créditos adicionais. B A descentralização de créditos orçamentários elimina a necessidade de transferência dos recursos financeiros correspondentes entre as unidades envolvidas. C A abertura de créditos suplementares exige autorização legislativa específica para cada alteração realizada durante a execução orçamentária. D A LOA pode conter autorização para abertura de créditos suplementares, permitindo determinadas retificações orçamentárias durante a execução do orçamento. E Os créditos extraordinários destinam-se às hipóteses de guerra, comoção interna ou calamidade pública, sendo vedada sua abertura por outra situação de urgência.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,69,$q$Planejamento e Controle Orçamentário$q$,$q$Acerca da classificação funcional da despesa orçamentária, julgue os itens subsequentes. I A classificação funcional busca evidenciar os montantes de recursos aplicados em áreas governamentais como educação, saúde e transportes. II As subfunções podem ser combinadas a funções diferentes daquelas às quais estejam originalmente vinculadas. III A classificação por categorias econômicas tem como finalidade principal demonstrar os objetivos governamentais a serem alcançados pelos programas orçamentários. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$Acerca da classificação funcional da despesa orçamentária, julgue os itens subsequentes. I A classificação funcional busca evidenciar os montantes de recursos aplicados em áreas governamentais como educação, saúde e transportes. II As subfunções podem ser combinadas a funções diferentes daquelas às quais estejam originalmente vinculadas. III A classificação por categorias econômicas tem como finalidade principal demonstrar os objetivos governamentais a serem alcançados pelos programas orçamentários. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,70,$q$Planejamento e Controle Orçamentário$q$,$q$Em relação ao processo orçamentário, julgue os próximos itens. I A iniciativa para apresentação do projeto de LOA é privativa do chefe do Poder Executivo. II O chefe do Poder Executivo pode encaminhar mensagem retificativa ao projeto de lei orçamentária, desde que ainda não tenha sido iniciada a votação da parte objeto da alteração na comissão competente. III Na apreciação das matérias orçamentárias, os parlamentares realizam estudos, discussões, consultas, solicitações de informações e participação em audiências públicas, sendo as emendas uma das principais formas de manifestação desse trabalho legislativo. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$Em relação ao processo orçamentário, julgue os próximos itens. I A iniciativa para apresentação do projeto de LOA é privativa do chefe do Poder Executivo. II O chefe do Poder Executivo pode encaminhar mensagem retificativa ao projeto de lei orçamentária, desde que ainda não tenha sido iniciada a votação da parte objeto da alteração na comissão competente. III Na apreciação das matérias orçamentárias, os parlamentares realizam estudos, discussões, consultas, solicitações de informações e participação em audiências públicas, sendo as emendas uma das principais formas de manifestação desse trabalho legislativo. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,71,$q$Planejamento e Controle Orçamentário$q$,$q$Durante auditoria em um contrato administrativo, a própria administração pública anulou ato ilegal praticado por um de seus órgãos. Posteriormente, o Congresso Nacional, com auxílio do TCU, realizou fiscalização sobre a aplicação dos recursos públicos. Paralelamente, a empresa contratada no âmbito daquele contrato administrativo ingressou com ação judicial, questionando a legalidade da decisão administrativa. A partir dessa situação hipotética, julgue os próximos itens. I A anulação do ato pela administração pública caracteriza exercício do controle interno, decorrente da fiscalização que a administração pública exerce sobre os próprios atos. II A fiscalização realizada pelo Congresso Nacional com auxílio do TCU caracteriza o controle externo exercido pelo Poder Legislativo. III No julgamento da ação judicial, a decisão do Poder Judiciário poderá substituir a da administração pública na análise da conveniência e da oportunidade do ato administrativo. Assinale a opção correta. A Nenhum item está certo. B Apenas o item II está certo. C Apenas o item III está certo. D Apenas os itens I e II estão certos. E Apenas os itens I e III estão certos.$q$,$q$Durante auditoria em um contrato administrativo, a própria administração pública anulou ato ilegal praticado por um de seus órgãos. Posteriormente, o Congresso Nacional, com auxílio do TCU, realizou fiscalização sobre a aplicação dos recursos públicos. Paralelamente, a empresa contratada no âmbito daquele contrato administrativo ingressou com ação judicial, questionando a legalidade da decisão administrativa. A partir dessa situação hipotética, julgue os próximos itens. I A anulação do ato pela administração pública caracteriza exercício do controle interno, decorrente da fiscalização que a administração pública exerce sobre os próprios atos. II A fiscalização realizada pelo Congresso Nacional com auxílio do TCU caracteriza o controle externo exercido pelo Poder Legislativo. III No julgamento da ação judicial, a decisão do Poder Judiciário poderá substituir a da administração pública na análise da conveniência e da oportunidade do ato administrativo. Assinale a opção correta. A Nenhum item está certo. B Apenas o item II está certo. C Apenas o item III está certo. D Apenas os itens I e II estão certos. E Apenas os itens I e III estão certos.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,72,$q$Planejamento e Controle Orçamentário$q$,$q$Considerando os tipos de auditoria aplicáveis ao setor público, seus conceitos e objetivos, assinale a opção correta. A As auditorias financeiras podem ser realizadas como trabalhos de certificação ou de relatório direto, conforme o objeto auditado e o nível de asseguração pretendido. B As auditorias operacionais e de conformidade têm formato padronizado de opinião, semelhante ao utilizado nas auditorias financeiras. C A auditoria operacional visa verificar se intervenções, programas ou instituições atuam em conformidade com os princípios de economicidade, eficiência, eficácia e efetividade, bem como identificar oportunidades de aperfeiçoamento da gestão. D A auditoria operacional é sempre um trabalho de certificação, cujo objetivo principal é a emissão de opinião padronizada acerca da conformidade das demonstrações financeiras. E A auditoria de conformidade tem por objetivo avaliar a eficiência, eficácia e efetividade de programas governamentais, sendo necessariamente um trabalho de relatório direto.$q$,$q$Considerando os tipos de auditoria aplicáveis ao setor público, seus conceitos e objetivos, assinale a opção correta. A As auditorias financeiras podem ser realizadas como trabalhos de certificação ou de relatório direto, conforme o objeto auditado e o nível de asseguração pretendido. B As auditorias operacionais e de conformidade têm formato padronizado de opinião, semelhante ao utilizado nas auditorias financeiras. C A auditoria operacional visa verificar se intervenções, programas ou instituições atuam em conformidade com os princípios de economicidade, eficiência, eficácia e efetividade, bem como identificar oportunidades de aperfeiçoamento da gestão. D A auditoria operacional é sempre um trabalho de certificação, cujo objetivo principal é a emissão de opinião padronizada acerca da conformidade das demonstrações financeiras. E A auditoria de conformidade tem por objetivo avaliar a eficiência, eficácia e efetividade de programas governamentais, sendo necessariamente um trabalho de relatório direto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,73,$q$Planejamento e Controle Orçamentário$q$,$q$No que diz respeito às finalidades e características do relatório resumido da execução orçamentária (RREO) e do relatório de gestão fiscal (RGF), assinale a opção correta. A O demonstrativo simplificado do RREO exclui as receitas e despesas intraorçamentárias para evitar duplicidade na consolidação das contas públicas. B O demonstrativo simplificado do RREO evidencia, em um único instrumento, informações como resultado primário e nominal, receita corrente líquida, restos a pagar e aplicação mínima em saúde e educação. C O RGF deve ser elaborado bimestralmente e apresentar informações extraídas do balanço orçamentário para demonstrar a execução da receita e da despesa acumuladas até o bimestre de referência. D O demonstrativo simplificado do RREO, emitido ao final de cada quadrimestre pelos titulares dos Poderes e órgãos, deve conter os limites de despesa com pessoal. E O RGF tem como principal objetivo demonstrar as previsões inicial e atualizada da receita e da despesa constantes na LOA.$q$,$q$No que diz respeito às finalidades e características do relatório resumido da execução orçamentária (RREO) e do relatório de gestão fiscal (RGF), assinale a opção correta. A O demonstrativo simplificado do RREO exclui as receitas e despesas intraorçamentárias para evitar duplicidade na consolidação das contas públicas. B O demonstrativo simplificado do RREO evidencia, em um único instrumento, informações como resultado primário e nominal, receita corrente líquida, restos a pagar e aplicação mínima em saúde e educação. C O RGF deve ser elaborado bimestralmente e apresentar informações extraídas do balanço orçamentário para demonstrar a execução da receita e da despesa acumuladas até o bimestre de referência. D O demonstrativo simplificado do RREO, emitido ao final de cada quadrimestre pelos titulares dos Poderes e órgãos, deve conter os limites de despesa com pessoal. E O RGF tem como principal objetivo demonstrar as previsões inicial e atualizada da receita e da despesa constantes na LOA.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,74,$q$Lei Anticorrupção$q$,$q$A Controladoria-Geral do Município de Porto Velho (CGM) instaurou processo administrativo de responsabilização contra três empresas — Alpha, Beta e Gama — integrantes do mesmo grupo econômico, pela suposta prática de atos lesivos à administração pública municipal consistentes em fraude ao caráter competitivo de licitação e pagamento de vantagem indevida a agentes públicos. No curso das investigações, a empresa Alpha, a primeira a manifestar interesse em colaborar, cessou imediatamente seu envolvimento nas infrações e admitiu sua participação nos ilícitos, tendo cooperado plena e permanentemente. As empresas Beta e Gama, embora integrem o mesmo grupo econômico, não aderiram ao acordo de leniência conjuntamente com Alpha. Dois anos após a assinatura do acordo de leniência, Alpha descumpriu parcialmente suas obrigações. Com base na Lei n.º 12.846/2013 (Lei Anticorrupção), assinale a opção correta em relação à situação hipotética apresentada. A Em razão do descumprimento parcial do acordo, Alpha ficará impedida de celebrar novo acordo de leniência pelo prazo de 3 anos contados do conhecimento, pela administração pública, do descumprimento, sem prejuízo do efeito interruptivo da prescrição dos atos ilícitos investigados já produzido no momento da celebração do acordo. B A CGM não detém competência para celebrar acordo de leniência de forma isolada, sendo obrigatória a participação do Ministério Público. C A proposta de acordo de leniência formulada por Alpha, ainda que rejeitada pela CGM, importaria o reconhecimento tácito da prática dos atos ilícitos investigados, podendo ser utilizada como elemento de prova em processo administrativo de responsabilização subsequente. D O acordo de leniência celebrado com a empresa Alpha a isenta da multa e da obrigação de reparar integralmente o dano causado, uma vez que a colaboração efetiva com as investigações substitui, para todos os fins, a reparação civil. E Os efeitos do acordo de leniência celebrado por Alpha se estendem automaticamente às empresas Beta e Gama, independentemente de adesão conjunta, em razão da solidariedade entre sociedades do mesmo grupo econômico.$q$,$q$A Controladoria-Geral do Município de Porto Velho (CGM) instaurou processo administrativo de responsabilização contra três empresas — Alpha, Beta e Gama — integrantes do mesmo grupo econômico, pela suposta prática de atos lesivos à administração pública municipal consistentes em fraude ao caráter competitivo de licitação e pagamento de vantagem indevida a agentes públicos. No curso das investigações, a empresa Alpha, a primeira a manifestar interesse em colaborar, cessou imediatamente seu envolvimento nas infrações e admitiu sua participação nos ilícitos, tendo cooperado plena e permanentemente. As empresas Beta e Gama, embora integrem o mesmo grupo econômico, não aderiram ao acordo de leniência conjuntamente com Alpha. Dois anos após a assinatura do acordo de leniência, Alpha descumpriu parcialmente suas obrigações. Com base na Lei n.º 12.846/2013 (Lei Anticorrupção), assinale a opção correta em relação à situação hipotética apresentada. A Em razão do descumprimento parcial do acordo, Alpha ficará impedida de celebrar novo acordo de leniência pelo prazo de 3 anos contados do conhecimento, pela administração pública, do descumprimento, sem prejuízo do efeito interruptivo da prescrição dos atos ilícitos investigados já produzido no momento da celebração do acordo. B A CGM não detém competência para celebrar acordo de leniência de forma isolada, sendo obrigatória a participação do Ministério Público. C A proposta de acordo de leniência formulada por Alpha, ainda que rejeitada pela CGM, importaria o reconhecimento tácito da prática dos atos ilícitos investigados, podendo ser utilizada como elemento de prova em processo administrativo de responsabilização subsequente. D O acordo de leniência celebrado com a empresa Alpha a isenta da multa e da obrigação de reparar integralmente o dano causado, uma vez que a colaboração efetiva com as investigações substitui, para todos os fins, a reparação civil. E Os efeitos do acordo de leniência celebrado por Alpha se estendem automaticamente às empresas Beta e Gama, independentemente de adesão conjunta, em razão da solidariedade entre sociedades do mesmo grupo econômico.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,75,$q$Lei Anticorrupção$q$,$q$A empresa Beta Engenharia Ltda., com sede no Brasil e filial em operação no Peru, foi contratada por um consórcio público binacional para execução de obras de infraestrutura. No curso do contrato, apurou-se que Beta: (i) se utilizara de uma pessoa jurídica interposta para ocultar a identidade dos reais beneficiários dos pagamentos realizados a agentes públicos peruanos vinculados ao consórcio; (ii) manipulara o equilíbrio econômico-financeiro do contrato por meio de aditivos fraudulentos sem amparo legal; e (iii) dificultara a atuação fiscalizatória de agentes de uma agência reguladora brasileira competente para supervisionar o contrato. Em sua defesa, Beta alegou que os atos praticados no Peru não se sujeitariam à Lei Anticorrupção, por terem sido praticados em território estrangeiro, e que o fato de sua filial peruana ter personalidade jurídica própria no ordenamento local afastaria a responsabilização da matriz no Brasil. Considerando a situação hipotética apresentada, assinale a opção correta de acordo com a Lei Anticorrupção. A As três condutas de Beta enumeradas configuram atos lesivos à administração pública, sendo improcedente a alegação defensiva da empresa tanto em relação à aplicação territorial da Lei Anticorrupção quanto no que diz respeito à responsabilização pela atuação da filial com sede no exterior. B A alegação defensiva de Beta é parcialmente procedente: os atos praticados no Peru ficam imunes à legislação brasileira, mas a manipulação do equilíbrio econômico-financeiro e a dificuldade à fiscalização, por terem produzido efeitos no território brasileiro, sujeitam-se normalmente à responsabilização administrativa nos termos do ordenamento pátrio. C A dificuldade imposta à atuação fiscalizatória dos agentes da agência reguladora brasileira não configura ato lesivo de responsabilização administrativa, pois consiste em conduta que afeta órgão técnico-regulatório desprovido de poder sancionatório direto sobre contratos administrativos binacionais. D A manipulação do equilíbrio econômico-financeiro do contrato por meio de aditivos fraudulentos não configura ato lesivo passível de responsabilização administrativa da pessoa jurídica, visto que a apuração da conduta é reservada exclusivamente ao processo licitatório e às instâncias de controle externo. E A utilização de pessoa jurídica interposta para ocultar a identidade dos reais beneficiários dos pagamentos somente configura ato lesivo se houver comprovação de dolo específico dos dirigentes de Beta, dado que a caracterização da utilização de interposta pessoa exige elemento subjetivo.$q$,$q$A empresa Beta Engenharia Ltda., com sede no Brasil e filial em operação no Peru, foi contratada por um consórcio público binacional para execução de obras de infraestrutura. No curso do contrato, apurou-se que Beta: (i) se utilizara de uma pessoa jurídica interposta para ocultar a identidade dos reais beneficiários dos pagamentos realizados a agentes públicos peruanos vinculados ao consórcio; (ii) manipulara o equilíbrio econômico-financeiro do contrato por meio de aditivos fraudulentos sem amparo legal; e (iii) dificultara a atuação fiscalizatória de agentes de uma agência reguladora brasileira competente para supervisionar o contrato. Em sua defesa, Beta alegou que os atos praticados no Peru não se sujeitariam à Lei Anticorrupção, por terem sido praticados em território estrangeiro, e que o fato de sua filial peruana ter personalidade jurídica própria no ordenamento local afastaria a responsabilização da matriz no Brasil. Considerando a situação hipotética apresentada, assinale a opção correta de acordo com a Lei Anticorrupção. A As três condutas de Beta enumeradas configuram atos lesivos à administração pública, sendo improcedente a alegação defensiva da empresa tanto em relação à aplicação territorial da Lei Anticorrupção quanto no que diz respeito à responsabilização pela atuação da filial com sede no exterior. B A alegação defensiva de Beta é parcialmente procedente: os atos praticados no Peru ficam imunes à legislação brasileira, mas a manipulação do equilíbrio econômico-financeiro e a dificuldade à fiscalização, por terem produzido efeitos no território brasileiro, sujeitam-se normalmente à responsabilização administrativa nos termos do ordenamento pátrio. C A dificuldade imposta à atuação fiscalizatória dos agentes da agência reguladora brasileira não configura ato lesivo de responsabilização administrativa, pois consiste em conduta que afeta órgão técnico-regulatório desprovido de poder sancionatório direto sobre contratos administrativos binacionais. D A manipulação do equilíbrio econômico-financeiro do contrato por meio de aditivos fraudulentos não configura ato lesivo passível de responsabilização administrativa da pessoa jurídica, visto que a apuração da conduta é reservada exclusivamente ao processo licitatório e às instâncias de controle externo. E A utilização de pessoa jurídica interposta para ocultar a identidade dos reais beneficiários dos pagamentos somente configura ato lesivo se houver comprovação de dolo específico dos dirigentes de Beta, dado que a caracterização da utilização de interposta pessoa exige elemento subjetivo.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,76,$q$Lei Anticorrupção$q$,$q$A CGM de Porto Velho concluiu processo administrativo de responsabilização contra a empresa Alfa Construções Ltda. pela prática continuada de atos lesivos entre 2018 e 2023. Constatou-se que os sócios administradores utilizaram a personalidade jurídica da empresa para encobrir os ilícitos e provocar confusão patrimonial, dificultando a reparação do dano ao erário municipal. Após a condenação, as sanções foram registradas no Cadastro Nacional de Empresas Punidas (CNEP) e comunicadas para atualização do Cadastro Nacional de Empresas Inidôneas e Suspensas (CEIS). Com base nessa situação hipotética e no disposto na Lei Anticorrupção, assinale a opção correta. A A comunicação ao órgão responsável pela atualização do CEIS é dispensável no caso, pois o CEIS e o CNEP têm o mesmo objeto e a mesma base legal, sendo redundante a manutenção de dois cadastros distintos para publicidade das sanções aplicadas com fundamento na Lei Anticorrupção. B Os valores arrecadados em razão de multas aplicadas à referida empresa devem ser destinados preferencialmente ao município de Porto Velho, na condição de ente lesado, e os registros das sanções no CNEP serão excluídos depois de decorrido o prazo previamente estabelecido no ato sancionador e da reparação do dano causado, mediante solicitação da CGM de Porto Velho. C Informações sobre eventual acordo de leniência proposto pela empresa devem ser inseridas no CNEP imediatamente após a propositura do acordo, independentemente de sua efetivação, para assegurar a publicidade e o controle social sobre as negociações em curso com a administração pública. D O marco inicial do prazo prescricional de cinco anos para a apuração da infração continuada praticada pela empresa é a data da prática do primeiro ato lesivo, em 2018, pois a partir desse momento a administração pública poderia ter tomado ciência da irregularidade. E Eventual desconsideração da personalidade jurídica da mencionada empresa somente seria cabível na esfera judicial, mediante ação ajuizada pelo Ministério Público ou pela advocacia pública, sendo vedada sua decretação no âmbito do processo administrativo de responsabilização.$q$,$q$A CGM de Porto Velho concluiu processo administrativo de responsabilização contra a empresa Alfa Construções Ltda. pela prática continuada de atos lesivos entre 2018 e 2023. Constatou-se que os sócios administradores utilizaram a personalidade jurídica da empresa para encobrir os ilícitos e provocar confusão patrimonial, dificultando a reparação do dano ao erário municipal. Após a condenação, as sanções foram registradas no Cadastro Nacional de Empresas Punidas (CNEP) e comunicadas para atualização do Cadastro Nacional de Empresas Inidôneas e Suspensas (CEIS). Com base nessa situação hipotética e no disposto na Lei Anticorrupção, assinale a opção correta. A A comunicação ao órgão responsável pela atualização do CEIS é dispensável no caso, pois o CEIS e o CNEP têm o mesmo objeto e a mesma base legal, sendo redundante a manutenção de dois cadastros distintos para publicidade das sanções aplicadas com fundamento na Lei Anticorrupção. B Os valores arrecadados em razão de multas aplicadas à referida empresa devem ser destinados preferencialmente ao município de Porto Velho, na condição de ente lesado, e os registros das sanções no CNEP serão excluídos depois de decorrido o prazo previamente estabelecido no ato sancionador e da reparação do dano causado, mediante solicitação da CGM de Porto Velho. C Informações sobre eventual acordo de leniência proposto pela empresa devem ser inseridas no CNEP imediatamente após a propositura do acordo, independentemente de sua efetivação, para assegurar a publicidade e o controle social sobre as negociações em curso com a administração pública. D O marco inicial do prazo prescricional de cinco anos para a apuração da infração continuada praticada pela empresa é a data da prática do primeiro ato lesivo, em 2018, pois a partir desse momento a administração pública poderia ter tomado ciência da irregularidade. E Eventual desconsideração da personalidade jurídica da mencionada empresa somente seria cabível na esfera judicial, mediante ação ajuizada pelo Ministério Público ou pela advocacia pública, sendo vedada sua decretação no âmbito do processo administrativo de responsabilização.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,77,$q$Lei Anticorrupção$q$,$q$O Ministério Público de determinado estado ajuizou ação judicial contra uma empresa do setor de construção, com base na Lei Anticorrupção, em razão da prática reiterada de atos lesivos à administração pública de certo município daquele estado. Verificou-se que a empresa fora originalmente constituída com o propósito de ocultar os reais beneficiários dos pagamentos realizados a agentes públicos. Paralelamente, a autoridade administrativa competente permaneceu inerte, sem instaurar o processo administrativo de responsabilização. Considerando a situação hipotética precedente, assinale a opção correta acerca da responsabilização judicial disciplinada pela Lei Anticorrupção. A Eventual requerimento de indisponibilidade de bens, direitos ou valores formulado pelo Ministério Público com fundamento na mencionada lei submete-se ao regime geral das tutelas de urgência, sendo necessária a demonstração de fumus boni iuris e periculum in mora, visto que se trata de medida cautelar de natureza excepcional. B O Ministério Público tem legitimidade para postular, pela via judicial, todas as sanções previstas na Lei Anticorrupção, inclusive as de natureza administrativa, independentemente de qualquer manifestação ou omissão prévia da autoridade administrativa competente para instaurar o processo de responsabilização. C As ações de responsabilização judicial ajuizadas com fundamento na Lei Anticorrupção devem observar o rito ordinário previsto no Código de Processo Civil, por terem natureza de ação civil de reparação de danos ao erário. D A dissolução compulsória da referida empresa somente seria cabível se constatado que sua personalidade jurídica foi utilizada de forma habitual para a prática dos atos ilícitos, sendo insuficiente, para tanto, a mera comprovação de que a empresa foi constituída com o propósito de ocultar os beneficiários dos pagamentos ilícitos. E O perdimento de bens, direitos ou valores que representem vantagem ou proveito direta ou indiretamente obtidos da infração pode ser requerido pelo Ministério Público ou pela advocacia pública para a garantia do pagamento da multa ou da reparação integral do dano, ressalvado o direito do terceiro de boa-fé; e, diante da omissão da autoridade administrativa, o Ministério Público pode postular em juízo a aplicação das sanções administrativas previstas na lei.$q$,$q$O Ministério Público de determinado estado ajuizou ação judicial contra uma empresa do setor de construção, com base na Lei Anticorrupção, em razão da prática reiterada de atos lesivos à administração pública de certo município daquele estado. Verificou-se que a empresa fora originalmente constituída com o propósito de ocultar os reais beneficiários dos pagamentos realizados a agentes públicos. Paralelamente, a autoridade administrativa competente permaneceu inerte, sem instaurar o processo administrativo de responsabilização. Considerando a situação hipotética precedente, assinale a opção correta acerca da responsabilização judicial disciplinada pela Lei Anticorrupção. A Eventual requerimento de indisponibilidade de bens, direitos ou valores formulado pelo Ministério Público com fundamento na mencionada lei submete-se ao regime geral das tutelas de urgência, sendo necessária a demonstração de fumus boni iuris e periculum in mora, visto que se trata de medida cautelar de natureza excepcional. B O Ministério Público tem legitimidade para postular, pela via judicial, todas as sanções previstas na Lei Anticorrupção, inclusive as de natureza administrativa, independentemente de qualquer manifestação ou omissão prévia da autoridade administrativa competente para instaurar o processo de responsabilização. C As ações de responsabilização judicial ajuizadas com fundamento na Lei Anticorrupção devem observar o rito ordinário previsto no Código de Processo Civil, por terem natureza de ação civil de reparação de danos ao erário. D A dissolução compulsória da referida empresa somente seria cabível se constatado que sua personalidade jurídica foi utilizada de forma habitual para a prática dos atos ilícitos, sendo insuficiente, para tanto, a mera comprovação de que a empresa foi constituída com o propósito de ocultar os beneficiários dos pagamentos ilícitos. E O perdimento de bens, direitos ou valores que representem vantagem ou proveito direta ou indiretamente obtidos da infração pode ser requerido pelo Ministério Público ou pela advocacia pública para a garantia do pagamento da multa ou da reparação integral do dano, ressalvado o direito do terceiro de boa-fé; e, diante da omissão da autoridade administrativa, o Ministério Público pode postular em juízo a aplicação das sanções administrativas previstas na lei.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,78,$q$Lei Anticorrupção$q$,$q$A CGM de Porto Velho concluiu processo administrativo de responsabilização contra determinada empresa de engenharia e a condenou por atos lesivos ao erário municipal. Apurou-se que a empresa não possuía faturamento bruto passível de aferição no exercício anterior à instauração do processo e que mantinha programa de integridade formalmente instituído, embora sua aplicação prática fosse deficiente. A autoridade deliberou pela aplicação cumulativa das duas sanções previstas na esfera administrativa. A respeito da responsabilização administrativa aplicável a esse caso hipotético, assinale a opção correta à luz da Lei Anticorrupção. A A reparação integral do dano causado somente é exigível após a conclusão de processo administrativo específico de reparação, instaurado em separado, e desde que as sanções já aplicadas se mostrem insuficientes para cobrir o prejuízo apurado. B A existência de mecanismos internos de integridade, auditoria e incentivo à denúncia de irregularidades, quando efetivamente aplicados, constitui causa excludente da responsabilização administrativa, afastando a aplicação das sanções previstas na esfera administrativa. C Na impossibilidade de apuração do faturamento bruto, a multa será fixada entre R$ 6 mil e R$ 60 milhões; as sanções podem ser aplicadas isoladamente ou cumulativamente, de forma fundamentada; e o programa de integridade, ainda que de aplicação deficiente, é fator a ser ponderado na dosimetria. D A base de cálculo da multa administrativa deve tomar por referência o faturamento bruto do último exercício anterior à prática do ato lesivo, excluídos os tributos, nunca podendo ser inferior à vantagem auferida quando possível sua estimação. E A publicação extraordinária da decisão condenatória ocorre na forma de extrato de sentença, custeada pelo erário, em meios de comunicação de grande circulação.$q$,$q$A CGM de Porto Velho concluiu processo administrativo de responsabilização contra determinada empresa de engenharia e a condenou por atos lesivos ao erário municipal. Apurou-se que a empresa não possuía faturamento bruto passível de aferição no exercício anterior à instauração do processo e que mantinha programa de integridade formalmente instituído, embora sua aplicação prática fosse deficiente. A autoridade deliberou pela aplicação cumulativa das duas sanções previstas na esfera administrativa. A respeito da responsabilização administrativa aplicável a esse caso hipotético, assinale a opção correta à luz da Lei Anticorrupção. A A reparação integral do dano causado somente é exigível após a conclusão de processo administrativo específico de reparação, instaurado em separado, e desde que as sanções já aplicadas se mostrem insuficientes para cobrir o prejuízo apurado. B A existência de mecanismos internos de integridade, auditoria e incentivo à denúncia de irregularidades, quando efetivamente aplicados, constitui causa excludente da responsabilização administrativa, afastando a aplicação das sanções previstas na esfera administrativa. C Na impossibilidade de apuração do faturamento bruto, a multa será fixada entre R$ 6 mil e R$ 60 milhões; as sanções podem ser aplicadas isoladamente ou cumulativamente, de forma fundamentada; e o programa de integridade, ainda que de aplicação deficiente, é fator a ser ponderado na dosimetria. D A base de cálculo da multa administrativa deve tomar por referência o faturamento bruto do último exercício anterior à prática do ato lesivo, excluídos os tributos, nunca podendo ser inferior à vantagem auferida quando possível sua estimação. E A publicação extraordinária da decisão condenatória ocorre na forma de extrato de sentença, custeada pelo erário, em meios de comunicação de grande circulação.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,79,$q$Lei Anticorrupção$q$,$q$Uma empresa foi responsabilizada em processo administrativo pelo pagamento de vantagem indevida a agente público. Durante o processo, a empresa, que mantinha contratos de elevado valor com o ente lesado, colaborou parcialmente com as investigações e apresentou programa de integridade robusto. A autoridade julgadora, ao dosar as sanções, desconsiderou o programa de integridade, por entender que ele não afastaria a responsabilidade objetiva da empresa. Considerando a situação hipotética apresentada, assinale a opção correta a respeito dos fatores de dosimetria aplicáveis ao caso, conforme a Lei Anticorrupção. A O valor dos contratos mantidos pela pessoa jurídica com o órgão lesado não integra o rol de fatores de dosimetria previstos na Lei Anticorrupção, por constituir elemento econômico alheio à conduta ilícita praticada e à sua gravidade intrínseca. B A autoridade julgadora incorreu em erro ao desconsiderar o programa de integridade, pois sua existência é fator de dosimetria expressamente previsto na Lei Anticorrupção, independentemente do afastamento ou não da responsabilização objetiva da pessoa jurídica. C A situação econômica da empresa infratora somente seria considerada como fator de dosimetria se a pessoa jurídica demonstrasse incapacidade financeira de arcar com a multa calculada sobre o faturamento bruto, hipótese em que a autoridade deveria aplicar o piso da faixa substitutiva. D A consumação ou não da infração é fator a ser considerado na dosimetria somente quando o ato lesivo tiver sido praticado em caráter tentado, sendo irrelevante ao se tratar de infrações que já produziram resultado danoso efetivo ao erário, como no caso em apreço. E A cooperação da pessoa jurídica para a apuração das infrações opera automaticamente como causa de redução obrigatória da multa, independentemente dos demais fatores de dosimetria, sendo vedado à autoridade manter a sanção em seu patamar máximo quando houver colaboração comprovada.$q$,$q$Uma empresa foi responsabilizada em processo administrativo pelo pagamento de vantagem indevida a agente público. Durante o processo, a empresa, que mantinha contratos de elevado valor com o ente lesado, colaborou parcialmente com as investigações e apresentou programa de integridade robusto. A autoridade julgadora, ao dosar as sanções, desconsiderou o programa de integridade, por entender que ele não afastaria a responsabilidade objetiva da empresa. Considerando a situação hipotética apresentada, assinale a opção correta a respeito dos fatores de dosimetria aplicáveis ao caso, conforme a Lei Anticorrupção. A O valor dos contratos mantidos pela pessoa jurídica com o órgão lesado não integra o rol de fatores de dosimetria previstos na Lei Anticorrupção, por constituir elemento econômico alheio à conduta ilícita praticada e à sua gravidade intrínseca. B A autoridade julgadora incorreu em erro ao desconsiderar o programa de integridade, pois sua existência é fator de dosimetria expressamente previsto na Lei Anticorrupção, independentemente do afastamento ou não da responsabilização objetiva da pessoa jurídica. C A situação econômica da empresa infratora somente seria considerada como fator de dosimetria se a pessoa jurídica demonstrasse incapacidade financeira de arcar com a multa calculada sobre o faturamento bruto, hipótese em que a autoridade deveria aplicar o piso da faixa substitutiva. D A consumação ou não da infração é fator a ser considerado na dosimetria somente quando o ato lesivo tiver sido praticado em caráter tentado, sendo irrelevante ao se tratar de infrações que já produziram resultado danoso efetivo ao erário, como no caso em apreço. E A cooperação da pessoa jurídica para a apuração das infrações opera automaticamente como causa de redução obrigatória da multa, independentemente dos demais fatores de dosimetria, sendo vedado à autoridade manter a sanção em seu patamar máximo quando houver colaboração comprovada.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$),
(2026,80,$q$Lei Anticorrupção$q$,$q$Ao final de processo administrativo de responsabilização contra uma empresa, foram aplicadas as sanções previstas na esfera administrativa e instaurado processo específico de reparação integral do dano. Concluído o processo de reparação, a empresa não efetuou o pagamento do crédito apurado. A partir dessa situação hipotética, assinale a opção correta de acordo com a Lei Anticorrupção. A A publicação extraordinária da decisão condenatória deve ser veiculada em meios de comunicação de grande circulação nacional, independentemente do local onde a infração tenha sido praticada ou onde a pessoa jurídica atua, dado o caráter exemplar da sanção. B O edital de publicação extraordinária da decisão condenatória deve ser afixado no estabelecimento da pessoa jurídica de modo visível ao público, no prazo mínimo de 30 dias, dispensando-se a publicação em sítio eletrônico quando regularmente efetivada a afixação física do edital no estabelecimento. C Como não houve pagamento após a conclusão do processo de reparação, o crédito apurado será inscrito em dívida ativa da fazenda pública, sendo admitida a publicação extraordinária da decisão condenatória na forma de extrato de sentença em publicação de circulação nacional apenas se inexistirem meios de grande circulação tanto na área da prática da infração quanto na área de atuação da pessoa jurídica. D A instauração do processo específico de reparação integral do dano impede a aplicação imediata das sanções previstas na esfera administrativa, visto que o quantum debeatur deve ser previamente liquidado para que as penalidades sejam fixadas com precisão. E A publicação extraordinária da decisão condenatória e a multa são sanções inacumuláveis na esfera administrativa, cabendo à autoridade julgadora optar por aquela que melhor atenda aos princípios da proporcionalidade e da razoabilidade no caso em apreço.$q$,$q$Ao final de processo administrativo de responsabilização contra uma empresa, foram aplicadas as sanções previstas na esfera administrativa e instaurado processo específico de reparação integral do dano. Concluído o processo de reparação, a empresa não efetuou o pagamento do crédito apurado. A partir dessa situação hipotética, assinale a opção correta de acordo com a Lei Anticorrupção. A A publicação extraordinária da decisão condenatória deve ser veiculada em meios de comunicação de grande circulação nacional, independentemente do local onde a infração tenha sido praticada ou onde a pessoa jurídica atua, dado o caráter exemplar da sanção. B O edital de publicação extraordinária da decisão condenatória deve ser afixado no estabelecimento da pessoa jurídica de modo visível ao público, no prazo mínimo de 30 dias, dispensando-se a publicação em sítio eletrônico quando regularmente efetivada a afixação física do edital no estabelecimento. C Como não houve pagamento após a conclusão do processo de reparação, o crédito apurado será inscrito em dívida ativa da fazenda pública, sendo admitida a publicação extraordinária da decisão condenatória na forma de extrato de sentença em publicação de circulação nacional apenas se inexistirem meios de grande circulação tanto na área da prática da infração quanto na área de atuação da pessoa jurídica. D A instauração do processo específico de reparação integral do dano impede a aplicação imediata das sanções previstas na esfera administrativa, visto que o quantum debeatur deve ser previamente liquidado para que as penalidades sejam fixadas com precisão. E A publicação extraordinária da decisão condenatória e a multa são sanções inacumuláveis na esfera administrativa, cabendo à autoridade julgadora optar por aquela que melhor atenda aos princípios da proporcionalidade e da razoabilidade no caso em apreço.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno Conhecimentos Específicos, Cargo 1: Auditor (CGM Porto Velho/RO 2026); gabarito conferido em 211_CGMROAUDITOR_001_01 (Google Drive). Base legal ainda não conferida item a item — aguardando revisão antes de content_status=active.$q$)
), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Controladoria-Geral do Município de Porto Velho (CGM/RO)' and role_name='Auditor' and contest_year=2026
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title=(case when imported.item_number<=30 then 'Prova objetiva CGM Porto Velho - Auditor - Conhecimentos Gerais - ' else 'Prova objetiva CGM Porto Velho - Auditor - Conhecimentos Específicos - ' end) || imported.exam_year
  join public.content_sources answer_source on answer_source.title=(case when imported.item_number<=30 then 'Gabarito definitivo CGM Porto Velho - Auditor - Conhecimentos Gerais - ' else 'Gabarito definitivo CGM Porto Velho - Auditor - Conhecimentos Específicos - ' end) || imported.exam_year
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Controladoria-Geral do Município de Porto Velho (CGM/RO)','Auditor','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
